// Polyfill for hashCode
if (!String.prototype.hashCode) {
    String.prototype.hashCode = function() {
        var hash = 0, i, chr;
        if (this.length === 0) return hash;
        for (i = 0; i < this.length; i++) {
            chr = this.charCodeAt(i);
            hash = ((hash << 5) - hash) + chr;
            hash |= 0; // Convert to 32bit integer
        }
        return hash;
    };
}




/* BACKEND-ONLY DATA MODE
 * - allData loaded via bootstrap() from /api (Postgres)
 * - UnityMasterFinanceRegistry accounts from FIN_COA_CRUD / chartsOfAccounts
 * - calculateTrialBalance must only aggregate transactions + COA (no mock amounts)
 */

const UnityMasterFinanceRegistry = ({ glassClass }) => {
  const { getCollection, allData } = useData();
  const [accounts, setAccounts] = useState([]);

  // COA from backend only (bootstrap → allData). No embedded mock registry.
  useEffect(() => {
    const coa =
      (typeof getCollection === 'function' ? getCollection('FIN_COA_CRUD') : null) ||
      allData?.FIN_COA_CRUD ||
      allData?.chartsOfAccounts ||
      [];
    const list = (Array.isArray(coa) ? coa : []).map((acc) => {
      // Never use UUID as Accounting Key
      const rawId = String(acc.id || '');
      const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(rawId);
      const code = String(
        acc.account_no || acc.account_code || acc['Accounting Key'] || (!isUuid ? acc.id : '') || ''
      ).replace(/^acc-/i, '').trim();
      const parts = code.split('-');
      const name = acc.desc || acc.name || acc.description || acc.short_desc || code;
      const typ = acc.type || acc.account_type || acc.group || 'General';
      return {
        ...acc,
        id: code, // Accounting Key
        account_no: code,
        account_code: code,
        base: acc.base || parts[0] || '',
        cc: acc.cc || parts[1] || '',
        loc: acc.loc || parts[2] || '',
        unit: acc.unit || (acc.cc === '01' || acc.cc === '1' ? 'General Administration' : (acc.cc ? `Unit ${acc.cc}` : 'General Administration')),
        campus: acc.campus || ({'10':'West Campus','11':'East Campus','12':'Gerji Campus','13':'Burayu Campus','14':'Adama Campus','15':'Dessie Campus','16':'Distance Ed'}[String(acc.loc||parts[2]||'10')] || 'West Campus'),
        desc: name,
        short_desc: acc.short_desc || name,
        type: typ,
        group: acc.group || typ,
        amount: Number(acc.amount || 0) || 0,
        status: acc.is_active === false ? 'Inactive' : (acc.status || 'Active'),
      };
    }).filter((a) => /^\d{4}-\d{2}-\d{2}$/.test(a.id));
    setAccounts(list);
  }, [getCollection, allData]);

  // Filter and Group States
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCampus, setSelectedCampus] = useState('ALL');
  const [selectedType, setSelectedType] = useState('ALL');
  const [groupBy, setGroupBy] = useState('NONE');

  // Add Record Modal/Form State
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [newAcc, setNewAcc] = useState({
    base: '',
    desc: '',
    type: 'Asset',
    cc: '01',
    loc: '10'
  });
  const [formError, setFormError] = useState('');

  // Unit and Campus mappings
  const unitMapping = {
    "01": "General Administration",
    "15": "Common Services",
    "41": "General Education (K-12)",
    "42": "TVET Programs",
    "43": "Undergraduate Program",
    "45": "Postgraduate Program",
    "50": "Cafeteria & Catering"
  };

  const campusMapping = {
    "10": "West Campus",
    "11": "East Campus",
    "12": "Gerji Campus",
    "13": "Burayu Campus",
    "14": "Adama Campus",
    "15": "Dessie Campus",
    "16": "Distance Ed",
    "18": "Kerchere Office"
  };

  // Extract unique options dynamically
  const campuses = useMemo(() => ['ALL', ...new Set(accounts.map(acc => acc.campus))], [accounts]);
  const types = ['ALL', 'Asset', 'Liability', 'Equity', 'Revenue', 'Expense'];
  // Submit Handler for New Record
  const handleAddAccount = (e) => {
    e.preventDefault();
    if (!newAcc.base || !newAcc.desc) {
      setFormError('Please fill out all required fields (Base Account, Description).');
      return;
    }

    const generatedId = `${newAcc.base}-${newAcc.cc}-${newAcc.loc}`;
    if (accounts.some(acc => acc.id === generatedId)) {
      setFormError(`Account ID "${generatedId}" already exists.`);
      return;
    }

    const unitName = unitMapping[newAcc.cc] || `Unit ${newAcc.cc}`;
    const campusName = campusMapping[newAcc.loc] || `Campus ${newAcc.loc}`;

    const entry = {
      id: generatedId,
      base: newAcc.base,
      cc: newAcc.cc,
      unit: unitName,
      loc: newAcc.loc,
      campus: campusName,
      desc: newAcc.desc,
      type: newAcc.type
    };

    setFormError('');
    setAccounts(prev => [entry, ...prev]);
    setIsAddModalOpen(false);
    setNewAcc({ base: '', desc: '', type: 'Asset', cc: '01', loc: '12' });
  };

  // Filter logic (dedupe by account id so React keys stay unique)
  const filteredAccounts = useMemo(() => {
    const seen = new Set();
    return accounts.filter(acc => {
      const id = String(acc.id || '');
      if (id && seen.has(id)) return false;
      if (id) seen.add(id);
      const matchesSearch = 
        id.toLowerCase().includes(searchTerm.toLowerCase()) ||
        String(acc.desc || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
        String(acc.base || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
        (acc.unit || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
        (acc.campus || '').toLowerCase().includes(searchTerm.toLowerCase());
      
      const matchesCampus = selectedCampus === 'ALL' || acc.campus === selectedCampus;
      const matchesType = selectedType === 'ALL' || acc.type === selectedType;

      return matchesSearch && matchesCampus && matchesType;
    });
  }, [accounts, searchTerm, selectedCampus, selectedType]);

  // Grouping logic
  const groupedAccounts = useMemo(() => {
    if (groupBy === 'NONE') return { 'All Accounts': filteredAccounts };

    return filteredAccounts.reduce((groups, account) => {
      const key = account[groupBy] || 'Unassigned';
      if (!groups[key]) groups[key] = [];
      groups[key].push(account);
      return groups;
    }, {});
  }, [filteredAccounts, groupBy]);

  return (
    <div className={`p-3 sm:p-4 md:p-6 ${glassClass || 'bg-slate-950 text-white'} rounded-3xl border border-white/20 shadow-2xl w-full min-h-0`}>
      
      {/* Header Section */}
      <div className="shrink-0 flex flex-col md:flex-row justify-between items-start md:items-center bg-black/40 p-4 sm:p-6 rounded-2xl border border-white/10 mb-4 gap-4">
        <div>
          <h2 className="text-3xl font-black italic tracking-tighter text-white">UNITY MASTER FINANCE REGISTRY</h2>
          <p className="text-cyan-400/60 text-xs font-mono mt-1">TOTAL IMPORTED RECORDS: {accounts.length}</p>
        </div>
        <button
          onClick={() => setIsAddModalOpen(true)}
          className="bg-cyan-600 hover:bg-cyan-500 text-white px-6 py-3 rounded-xl font-black text-xs transition-all shadow-xl shadow-cyan-900/40 uppercase tracking-widest"
        >
          + Register New Account
        </button>
      </div>

      {/* FILTER & GROUP CONTROL PANEL */}
      <div className="mb-6 p-4 bg-white/5 backdrop-blur-md rounded-2xl border border-white/10 flex flex-wrap gap-4 items-center justify-between">
        <div className="flex flex-col flex-1 min-w-[220px]">
          <label className="text-[10px] font-black uppercase tracking-widest mb-1 text-cyan-400">Search Master Ledger</label>
          <input 
            type="text" 
            placeholder="Search accounts, codes, descriptions..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="px-4 py-3 rounded-xl border border-white/10 text-sm bg-white/5 text-white focus:outline-none focus:border-cyan-500"
          />
        </div>

        <div className="flex flex-col min-w-[220px]">
          <label className="text-[10px] font-black uppercase tracking-widest mb-1 text-cyan-400">Filter by Campus</label>
          <UUSelect
            value={selectedCampus}
            onChange={setSelectedCampus}
            options={campuses}
            allLabel="ALL"
          />
        </div>

        <div className="flex flex-col min-w-[220px]">
          <label className="text-[10px] font-black uppercase tracking-widest mb-1 text-cyan-400">Filter by Type</label>
          <UUSelect
            value={selectedType}
            onChange={setSelectedType}
            options={types}
            allLabel="ALL"
          />
        </div>

        <div className="flex flex-col min-w-[220px]">
          <label className="text-[10px] font-black uppercase tracking-widest mb-1 text-cyan-400">Group By</label>
          <UUSelect
            value={groupBy}
            onChange={setGroupBy}
            options={[
              { value: 'NONE', label: 'No Grouping' },
              { value: 'campus', label: 'Campus' },
              { value: 'type', label: 'Type' },
              { value: 'unit', label: 'Unit' },
            ]}
          />
        </div>
      </div>

      {/* ADD RECORD MODAL */}
      {isAddModalOpen && (
        <div
          className="fixed inset-0 flex items-start justify-center bg-slate-950/35 backdrop-blur-[2px] p-4 pt-20 sm:pt-24 overflow-y-auto"
          style={{ position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, zIndex: 2147483000 }}
        >
          <div
            className="bg-slate-900 border-2 border-cyan-400 rounded-3xl shadow-[0_20px_50px_rgba(0,0,0,0.5)] w-full max-w-2xl relative"
            onClick={(e) => e.stopPropagation()}
            onMouseDown={(e) => e.stopPropagation()}
          >
            <div className="flex justify-between items-center mb-6 pb-4 border-b border-white/10">
              <h3 className="text-xl font-black text-white italic tracking-tighter uppercase">Add New Chart of Account Record</h3>
              <button 
                onClick={() => setIsAddModalOpen(false)}
                className="text-white/40 hover:text-white font-bold text-xl p-2"
              >
                &times;
              </button>
            </div>

            <form onSubmit={handleAddAccount} className="space-y-4">
              {formError && (
                <div className="p-3 bg-red-900/40 border border-red-500/50 text-red-200 text-sm rounded-xl">
                  {formError}
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-semibold text-gray-300 mb-1">Base Account *</label>
                  <input 
                    type="text" 
                    placeholder="e.g. 1130" 
                    value={newAcc.base} 
                    onChange={e => setNewAcc({ ...newAcc, base: e.target.value })}
                    className="w-full px-4 py-3 rounded-xl border border-white/10 text-sm bg-white/5 text-white focus:border-cyan-500 outline-none"
                    required
                  />
                </div>

                <div>
                  <label className="block text-xs font-semibold text-gray-300 mb-1">Account Type</label>
                  <UUSelect
                    value={newAcc.type}
                    onChange={(v) => setNewAcc({ ...newAcc, type: v })}
                    options={['Asset', 'Liability', 'Equity', 'Revenue', 'Expense']}
                  />
                </div>

                <div>
                  <label className="block text-xs font-semibold text-gray-300 mb-1">Cost Center (CC)</label>
                  <UUSelect
                    value={newAcc.cc}
                    onChange={(v) => setNewAcc({ ...newAcc, cc: v })}
                    options={Object.entries(unitMapping).map(([code, name]) => ({ value: code, label: `${code} - ${name}` }))}
                  />
                </div>

                <div>
                  <label className="block text-xs font-semibold text-gray-300 mb-1">Location / Campus</label>
                  <UUSelect
                    value={newAcc.loc}
                    onChange={(v) => setNewAcc({ ...newAcc, loc: v })}
                    options={Object.entries(campusMapping).map(([code, name]) => ({ value: code, label: `${code} - ${name}` }))}
                  />
                </div>

                <div className="md:col-span-2">
                  <label className="block text-xs font-semibold text-gray-300 mb-1">Description *</label>
                  <input 
                    type="text" 
                    placeholder="e.g. Cash in Bank - Main Account" 
                    value={newAcc.desc} 
                    onChange={e => setNewAcc({ ...newAcc, desc: e.target.value })}
                    className="w-full px-4 py-3 rounded-xl border border-white/10 text-sm bg-white/5 text-white focus:border-cyan-500 outline-none"
                    required
                  />
                </div>
              </div>

              <div className="flex justify-end gap-3 pt-4 border-t border-white/10">
                <button
                  type="button"
                  onClick={() => setIsAddModalOpen(false)}
                  className="px-5 py-3 border border-white/20 rounded-xl text-sm font-medium text-gray-300 hover:bg-white/5"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-6 py-3 bg-cyan-600 hover:bg-cyan-500 text-white rounded-xl text-sm font-black shadow-lg shadow-cyan-900/40 uppercase tracking-widest"
                >
                  Save Record
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* COA table — free vertical scroll with page; borders stay on cells */}
      <div className="w-full rounded-2xl border-2 border-white/25 bg-black/50 overflow-hidden">
        <div className="w-full overflow-x-auto overflow-y-visible">
          <table className="w-full border-collapse text-left text-sm text-gray-300" style={{ tableLayout: 'fixed', width: '100%', minWidth: '640px' }}>
            <colgroup>
              <col style={{ width: '14%' }} />
              <col style={{ width: '8%' }} />
              <col style={{ width: '16%' }} />
              <col style={{ width: '14%' }} />
              <col style={{ width: '28%' }} />
              <col style={{ width: '10%' }} />
              <col style={{ width: '10%' }} />
            </colgroup>
            <thead className="sticky top-0 z-20">
              <tr className="text-[10px] text-cyan-400 font-black uppercase tracking-widest bg-slate-900">
                <th className="px-2 py-2.5 border border-white/25 bg-slate-900">Accounting Key</th>
                <th className="px-2 py-2.5 border border-white/25 bg-slate-900">Base</th>
                <th className="px-2 py-2.5 border border-white/25 bg-slate-900">Unit Name</th>
                <th className="px-2 py-2.5 border border-white/25 bg-slate-900">Campus Scope</th>
                <th className="px-2 py-2.5 border border-white/25 bg-slate-900">Description</th>
                <th className="px-2 py-2.5 border border-white/25 bg-slate-900">Type</th>
                <th className="px-2 py-2.5 border border-white/25 bg-slate-900 text-right font-mono text-white/40">CC / Loc</th>
              </tr>
            </thead>
            <tbody>
              {Object.entries(groupedAccounts).map(([groupName, groupItems]) => (
                <React.Fragment key={groupName}>
                  {groupBy !== 'NONE' && (
                    <tr className="bg-slate-900/90">
                      <td colSpan={7} className="px-2 py-2 text-xs tracking-wider uppercase text-cyan-300 border border-white/25">
                        Group: {groupName} <span className="text-white/40">({groupItems.length})</span>
                      </td>
                    </tr>
                  )}
                  {groupItems.map((acc, index) => (
                    <tr key={`${acc.id || 'acc'}-${index}`} className="hover:bg-cyan-500/5">
                      <td className="px-2 py-1.5 font-mono text-cyan-400 font-bold text-xs border border-white/20 truncate" title={acc.id}>{acc.id}</td>
                      <td className="px-2 py-1.5 font-mono text-xs border border-white/20 truncate">{acc.base}</td>
                      <td className="px-2 py-1.5 text-xs font-semibold border border-white/20 truncate" title={acc.unit}>{acc.unit}</td>
                      <td className="px-2 py-1.5 text-xs text-cyan-300 font-semibold border border-white/20 truncate">{acc.campus}</td>
                      <td className="px-2 py-1.5 text-xs text-white border border-white/20 truncate" title={acc.desc || acc.short_desc}>{acc.desc || acc.short_desc}</td>
                      <td className="px-2 py-1.5 text-xs uppercase italic border border-white/20 truncate">{acc.type}</td>
                      <td className="px-2 py-1.5 text-right text-[10px] font-mono text-white/40 border border-white/20">{[acc.cc, acc.loc].filter(Boolean).join(' / ') || '—'}</td>
                    </tr>
                  ))}
                </React.Fragment>
              ))}
              {accounts.length === 0 && (
                <tr>
                  <td colSpan={7} className="px-4 py-8 text-center text-white/40 border border-white/20">No chart of accounts rows loaded.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

    </div>
  );
};



const exportToExcelRobustTable = () => {
    const workbook = XLSX.utils.book_new();

    const createDesignerSheet = (data, title, sheetName) => {
        // Build the AOA with spacing and frames logic
        const aoa = [
            ["", "", "", "", ""], // Pad top
            ["", title.toUpperCase(), "", "", ""], // Row 1: Title
            ["", "DATE GENERATED:", new Date().toLocaleDateString(), "", ""], // Row 2: Date
            ["", "", "", "", ""], // Spacer
            ["", "NOTE", "DESCRIPTION", "AMOUNT (ETB)", "TOTAL"], // Row 4: Table Headers
        ];

        // Add Data Rows
        data.forEach(item => {
            aoa.push([
                "",             // Frame Padding
                item[1] || "-", // Note
                item[2] || "",  // Description
                item[4] || 0,   // Amount
                ""              // Subtotal placeholder
            ]);
        });

        // Add a Footer spacer
        aoa.push(["", "", "", "", ""]);

        const ws = XLSX.utils.aoa_to_sheet(aoa);

        // --- ROBUST STYLING (Cell Logic) ---

        // 1. Column Widths - Framing the look
        ws['!cols'] = [
            { wch: 5 },  // Left Margin
            { wch: 12 }, // Note
            { wch: 55 }, // Description (Wide for clarity)
            { wch: 20 }, // Amount
            { wch: 20 }  // Total
        ];

        // 2. Merging for the "Framed Header" look
        ws['!merges'] = [
            { s: { r: 1, c: 1 }, e: { r: 1, c: 4 } }, // Merge Title across main columns
            { s: { r: 2, c: 2 }, e: { r: 2, c: 3 } }  // Merge Date value
        ];

        // 3. Grid / Framing Metadata
        // Note: Standard 'xlsx' lib doesn't support fill/font color without 'xlsx-js-style'.
        // To provide the *best* visual for standard xlsx, we use clean alignment and padding.
        
        return ws;
    };

    const plData = [
        ["", "1", "Revenue from Education Services", "", 1250000],
        ["", "2", "Cost of Sales / Academic Costs", "", -720000],
        ["", "", "GROSS PROFIT", "", 530000],
        ["", "3", "Administrative Expenses", "", -180000],
        ["", "4", "Marketing & Distribution", "", -35000],
        ["", "5", "Other Operating Expenses", "", -50000],
        ["", "", "OPERATING PROFIT", "", 280000],
        ["", "6", "Finance Costs", "", -12000],
        ["", "7", "Income Tax Expense (25%)", "", -67000],
        ["", "", "NET PROFIT FOR THE YEAR", "", 201000]
    ];

    const fpData = [
        ["", "8", "Property, Plant and Equipment", "", 450000],
        ["", "9", "Intangible Assets", "", 50000],
        ["", "10", "Inventories", "", 180000],
        ["", "11", "Trade and Other Receivables", "", 115000],
        ["", "12", "Cash and Bank Balances", "", 245000],
        ["", "13", "Share Capital", "", 500000],
        ["", "14", "Retained Earnings", "", 210000],
        ["", "15", "Long-term Loans", "", 200000],
        ["", "16", "Trade and Other Payables", "", 90000],
        ["", "", "TOTAL ASSETS/EQUITY", "", 1040000]
    ];

    XLSX.utils.book_append_sheet(workbook, createDesignerSheet(plData, "Statement of Profit or Loss", "PLCINc"), "PLCINc");
    XLSX.utils.book_append_sheet(workbook, createDesignerSheet(fpData, "Statement of Financial Position", "BalanceSheet"), "Fin-Pos");

    XLSX.writeFile(workbook, "Unity_Designed_Financial_Report.xlsx");
};
