const generateRobustWorkbook = async (data, filename) => {
    const workbook = new ExcelJS.Workbook();
    const worksheet = workbook.addWorksheet("Statement");

    // Exact Template Column Widths
    worksheet.getColumn(1).width = 5;   // Margin
    worksheet.getColumn(2).width = 50;  // Account Designation
    worksheet.getColumn(3).width = 10;  // Notes
    worksheet.getColumn(4).width = 22;  // Current Year
    worksheet.getColumn(5).width = 22;  // Prior Year

    // 1. Branding Headers
    worksheet.mergeCells('B2:E2');
    const tCell = worksheet.getCell('B2');
    tCell.value = "UNITY UNIVERSITY PLC";
    tCell.font = { bold: true, size: 16, italic: true };
    tCell.alignment = { horizontal: 'center' };

    worksheet.mergeCells('B3:E3');
    const sCell = worksheet.getCell('B3');
    sCell.value = filename.toUpperCase() + " (Official Record)";
    sCell.font = { bold: true, size: 12 };
    sCell.alignment = { horizontal: 'center' };

    // 2. Styled Table Header
    const hRow = worksheet.addRow(["", "Account Designation", "Notes", "Current Amount", "Previous Year"]);
    hRow.eachCell((cell, colNumber) => {
        if (colNumber > 1) {
            cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
            cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1F4E78' } };
            cell.alignment = { horizontal: colNumber === 2 ? 'left' : 'right' };
            cell.border = { bottom: { style: 'thin' } };
        }
    });

    // 3. Populate Rows with Logic
    data.forEach((item) => {
        const row = worksheet.addRow([
            "", 
            item.label || item.designation, 
            item.note || "", 
            item.v25 || item.amount || 0,
            item.v24 || 0
        ]);

        const labelCell = row.getCell(2);
        const amtCellCurrent = row.getCell(4);
        const amtCellPrior = row.getCell(5);

        // Styling based on row metadata
        if (item.indent) labelCell.alignment = { indent: item.indent * 2 };
        if (item.isBold || item.type === 'total' || item.type === 'grand-total' || item.isHeader) {
            labelCell.font = { bold: true };
            amtCellCurrent.font = { bold: true };
            if (item.type === 'total') amtCellCurrent.border = { top: { style: 'thin' } };
            if (item.type === 'grand-total') {
                amtCellCurrent.border = { top: { style: 'thin' }, bottom: { style: 'double' } };
            }
        }

        // Formatting currency
        [amtCellCurrent, amtCellPrior].forEach(c => {
            c.numFmt = '#,##0.00;[Red](#,##0.00)';
            c.alignment = { horizontal: 'right' };
        });
    });

    const buffer = await workbook.xlsx.writeBuffer();
    saveAs(new Blob([buffer]), `${filename.replace(/\s+/g, '_')}.xlsx`);
};

/**
 * Robust Wrapper for Word (DOCX)
 */
const generateRobustDOCX = async (data, filename, isFinancial) => {
    const { Document, Packer, Paragraph, Table, TableCell, TableRow, WidthType, AlignmentType, TextRun, ShadingType } = docx;

    const tableRows = [
        new TableRow({
            children: (isFinancial ? ["Designation", "Note", "Amount"] : ["Field", "Information"]).map(h => new TableCell({
                children: [new Paragraph({ children: [new TextRun({ text: h.toUpperCase(), bold: true, color: "FFFFFF", size: 20 })], alignment: AlignmentType.CENTER })],
                shading: { fill: "1F4E78", type: ShadingType.CLEAR },
            })),
        }),
        ...data.map((item, i) => new TableRow({
            children: isFinancial ? [
                new TableCell({ children: [new Paragraph({ children: [new TextRun({ text: item.label, bold: item.isBold, size: 18 })] })], shading: i % 2 === 0 ? { fill: "F8FAFC" } : undefined }),
                new TableCell({ children: [new Paragraph({ text: String(item.note || "-"), alignment: AlignmentType.CENTER })] }),
                new TableCell({ children: [new Paragraph({ text: String(item.amount || 0), alignment: AlignmentType.RIGHT })] }),
            ] : [
                new TableCell({ children: [new Paragraph({ text: String(Object.keys(item)[0]), bold: true })] }),
                new TableCell({ children: [new Paragraph({ text: String(Object.values(item)[0]) })] }),
            ]
        }))
    ];

    const doc = new Document({
        sections: [{
            children: [
                new Paragraph({ text: "UNITY UNIVERSITY PLC", bold: true, size: 36 }),
                new Paragraph({ text: filename.toUpperCase(), bold: true, size: 24, spacing: { after: 300 } }),
                new Table({ width: { size: 100, type: WidthType.PERCENTAGE }, rows: tableRows })
            ],
        }],
    });
    const blob = await Packer.toBlob(doc);
    saveAs(blob, `${filename}.docx`);
};

