/* ===== Material ↔ Finance ledger bridge ===== */
const UU_MAT_LEDGER_KEY = 'uu_shared_material_ledger_v1';
const UU_FIN_COA_KEY = 'uu_shared_finance_coa_v1';
const uuLoadMatLedger = () => {
    try {
        const v = JSON.parse(localStorage.getItem(UU_MAT_LEDGER_KEY) || '[]');
        return Array.isArray(v) ? v : [];
    } catch { return []; }
};
const uuPublishFinanceCoa = (coa) => {
    try {
        if (Array.isArray(coa) && coa.length) {
            localStorage.setItem(UU_FIN_COA_KEY, JSON.stringify(coa));
        }
    } catch (e) {}
};
const uuMergeMaterialLegs = (localTx = []) => {
    // BACKEND-ONLY: do not inject localStorage material mocks into the ledger.
    // Material posts must arrive via API bootstrap / fin_transactions from Postgres.
    return Array.isArray(localTx) ? localTx : [];
};


/* ===== HR ↔ Finance integration (no extra module) ===== */
const UU_HR_EMP_KEY = 'uu_shared_hr_employees_v1';
const uuLoadHrEmployees = () => {
    try {
        const raw = localStorage.getItem(UU_HR_EMP_KEY);
        if (!raw) return [];
        const v = JSON.parse(raw);
        return Array.isArray(v) ? v : [];
    } catch { return []; }
};
const uuSaveHrEmployees = (list) => {
    try {
        localStorage.setItem(UU_HR_EMP_KEY, JSON.stringify(Array.isArray(list) ? list : []));
    } catch (e) {}
};
const uuNormHrEmp = (e) => {
    if (!e || typeof e !== 'object') return null;
    const name = e.name || e.employee_name || e.full_name || '';
    if (!name) return null;
    return {
        ...e,
        name,
        employee_name: name,
        id_number: e.id_number || e.idNo || '',
        job_title: e.job_title || e.position || '',
        position: e.job_title || e.position || '',
        department: e.department || e.dept || '',
        work_location: e.work_location || e.location || '',
        gross_salary: e.gross_salary ?? e.current_salary ?? e.basic_salary ?? 0,
        basic_salary: e.gross_salary ?? e.current_salary ?? e.basic_salary ?? 0,
        pension_id: e.pension_id || e.pension_ac || '',
        tin_no: e.tin_no || e.tin || '',
        national_id: e.national_id || '',
        telephone_number: e.telephone_number || e.mobile || '',
        seniority_date_gc: e.seniority_date_gc || e.seniority_date || '',
        employment_type: e.employment_type || '',
        employment_category: e.employment_category || '',
        status: e.status || 'Active',
    };
};
const uuMergeHrEmployees = (local = []) => {
    const dropDemo = (n) => {
        if (!n) return null;
        const name = String(n.name || n.full_name || n.employee_name || '').trim();
        if (!name) return null;
        if (/^staff member\s*\d*$/i.test(name)) return null;
        if (/^ultimate sample/i.test(name)) return null;
        return n;
    };
    const by = new Map();
    const put = (e) => {
        const n = dropDemo(typeof uuNormHrEmp === 'function' ? uuNormHrEmp(e) : e);
        if (!n) return;
        const k = String(n.id_number || n.id || n.name).toLowerCase().trim();
        if (!k) return;
        by.set(k, { ...(by.get(k) || {}), ...n });
    };
    // Finance in-memory rows (may be stale)
    (Array.isArray(local) ? local : []).forEach(put);
    // Live Employee Master published by HR module (always overlays same id/name)
    try {
        const shared = typeof uuLoadHrEmployees === 'function' ? uuLoadHrEmployees() : [];
        (Array.isArray(shared) ? shared : []).forEach(put);
    } catch (e) {}
    return Array.from(by.values());
};
const uuPublishHrEmployees = (list) => {
    // Full replace of shared HR cache so Finance select matches HR master
    const cleaned = (list || []).map(uuNormHrEmp).filter((n) => {
        if (!n) return false;
        const name = String(n.name || '').trim();
        return name && !/^staff member\s*\d*$/i.test(name);
    });
    uuSaveHrEmployees(cleaned);
    return cleaned;
};


