    /** Expand a single-entry / journal header into two balanced legs for TB/GL */
    const expandToBalancedLegs = (rec, sourceTag) => {
        if (!rec) return [];
        const clean = (v) => String(v || '').replace(/^acc-/i, '').trim();
        const isValid = (c) => /^\d{4}-\d{2}-\d{2}$/.test(c);
        const date = rec.date || rec.posting_date || new Date().toISOString().split('T')[0];
        const narr = String(rec.description || rec.narration || rec.reference || 'Entry');
        const partner = rec.partner_name || rec.entity || '';
        const status = rec.status || 'Posted';
        const jid = rec.journal_id || rec.id || '';
        const primaryCode = clean(rec.account_id || rec.account_code || rec.account_no || '');
        const balCode = clean(rec.balancing_account || rec.balancing_account_id || '');
        let debit = Number(rec.debit || 0);
        let credit = Number(rec.credit || 0);
        const amt = Number(rec.amount || rec.total_debit || rec.total_credit || 0);
        if ((!debit && !credit) && amt > 0) {
            const t = String(rec.type || '').toLowerCase();
            if (t.startsWith('d') || t === 'dr') debit = amt;
            else credit = amt;
        }
        if (!Number.isFinite(debit)) debit = 0;
        if (!Number.isFinite(credit)) credit = 0;
        if (debit <= 0 && credit <= 0) return [];

        const legs = [];
        if (isValid(primaryCode)) {
            legs.push({
                id: String(rec.id || jid) + '-P',
                date,
                journal_id: jid,
                partner_name: partner,
                account_id: primaryCode,
                account_code: primaryCode,
                account_no: primaryCode,
                account_name: rec.account_name || primaryCode,
                type: debit > 0 ? 'Debit' : 'Credit',
                amount: debit > 0 ? debit : credit,
                debit,
                credit,
                description: narr,
                narration: narr,
                reference: rec.reference || jid,
                status,
                module: rec.module || (sourceTag === 'DAY_JOURNAL' ? 'JOURNAL' : 'MANUAL'),
                source: sourceTag || rec.source || 'SINGLE_TXN',
                isMock: false,
                isSystemFrame: false
            });
        }
        // Contra leg — only if balancing account is a different valid code
        if (isValid(balCode) && balCode !== primaryCode) {
            const bDr = debit > 0 ? 0 : (Number(rec.balancing_amount) || credit || debit);
            const bCr = debit > 0 ? (Number(rec.balancing_amount) || debit || credit) : 0;
            legs.push({
                id: String(rec.id || jid) + '-S',
                date,
                journal_id: jid,
                partner_name: partner,
                account_id: balCode,
                account_code: balCode,
                account_no: balCode,
                account_name: rec.balancing_account_name || balCode,
                type: bDr > 0 ? 'Debit' : 'Credit',
                amount: bDr > 0 ? bDr : bCr,
                debit: bDr,
                credit: bCr,
                description: narr.startsWith('Contra:') ? narr : ('Contra: ' + narr),
                narration: narr.startsWith('Contra:') ? narr : ('Contra: ' + narr),
                reference: rec.reference || jid,
                status,
                module: rec.module || (sourceTag === 'DAY_JOURNAL' ? 'JOURNAL' : 'MANUAL'),
                source: sourceTag || rec.source || 'SINGLE_TXN',
                isMock: false,
                isSystemFrame: false
            });
        }
        return legs;
    };

