// PATH A: ROBUST FINANCIAL GENERATOR (Matches your Excel Template)

// ========================================================================
// 3. DATATABLE COMPONENT (NOW USES THE GENERIC EXPORT)
// ========================================================================

const DataTable = ({ collectionName, data, columns: columnsProp, glassClass, title, getCollection }) => {
    const columns = (Array.isArray(columnsProp) ? columnsProp : []).filter((c) => c && typeof c === 'object' && c.key);
    const { deleteRecord, updateRecord, commitAllPayroll } = useData();
    const { checkPermission } = useAuth();
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingRecord, setEditingRecord] = useState(null);
    const [searchTerm, setSearchTerm] = useState("");
    const [statusFilter, setStatusFilter] = useState("All");
    const [periodFilter, setPeriodFilter] = useState("All");
    const [listTick, setListTick] = useState(0);
    const closeModal = React.useCallback(() => {
        setIsModalOpen(false);
        setEditingRecord(null);
        setListTick((n) => n + 1);
    }, []);

    const allRoles = useMemo(() => getCollection('ROLE_CRUD') || [], [getCollection]);

    // Safe filter option lists (never reference undefined identifiers)
    const statusOptions = useMemo(() => {
        const s = new Set(['All']);
        const raw = (typeof getCollection === 'function' ? getCollection(collectionName) : null);
        const rows = Array.isArray(raw) ? raw : (Array.isArray(data) ? data : []);
        rows.forEach((r) => {
            if (r && r.status != null && String(r.status).trim()) s.add(String(r.status));
        });
        ['Active', 'Pending', 'Committed', 'Approved', 'Inactive', 'Posted', 'Draft'].forEach((x) => s.add(x));
        return Array.from(s);
    }, [getCollection, collectionName, data]);

    const periodOptions = useMemo(() => {
        const s = new Set(['All']);
        const raw = (typeof getCollection === 'function' ? getCollection(collectionName) : null);
        const rows = Array.isArray(raw) ? raw : (Array.isArray(data) ? data : []);
        rows.forEach((r) => {
            const p = r?.period || r?.month || r?.payroll_period;
            if (p != null && String(p).trim()) s.add(String(p));
        });
        return Array.from(s);
    }, [getCollection, collectionName, data]);
    const dataMemo = useMemo(() => {
        const raw = (typeof getCollection === 'function' ? getCollection(collectionName) : null);
        const rows = (Array.isArray(raw) ? raw : Array.isArray(data) ? data : []).filter((r) => r && typeof r === 'object');
        // Single Transaction board: only single-txn / payroll / manual legs (journals stay on Journal board)
        if (collectionName === 'transactions') {
            return rows.filter((r) => {
                const src = String(r.source || r.module || '').toUpperCase();
                if (src === 'DAY_JOURNAL' || src === 'JOURNAL') return false;
                return true;
            });
        }
        return rows;
    }, [getCollection, collectionName, data, listTick]);
    const isPayrollModule = ['PAY_MASTER_CRUD','PAY_OVERTIME_CRUD','PAY_AD_CRUD','PAY_PROCESS_CRUD','PAY_RECON_CRUD','PAY_FACTOR_MASTER_CRUD'].includes(collectionName);
    const isFinanceModule = ['transactions', 'dayJournals', 'FIN_PARTNERS_CRUD', 'FIN_COA_CRUD', 'chartsOfAccounts'].includes(collectionName);

    const getAddLabel = () => {
        const labels = {
            'HR_EMPLOYEE_CRUD': 'Employee', 'HR_LEAVE_CRUD': 'Leave',
            'HR_PENALTY_CRUD': 'Penalty', 'RETIREMENT_CRUD': 'Retirement',
            'PAY_MASTER_CRUD': 'Salary Master', 'PAY_OVERTIME_CRUD': 'OT Entry',
            'PAY_AD_CRUD': 'Allowance/Deduction', 'PAY_PROCESS_CRUD': 'Process Row', 'PAY_RECON_CRUD': 'Reconciliation',
            'transactions': 'Single Transaction', 'dayJournals': 'Journal Entry',
            'FIN_PARTNERS_CRUD': 'Partner', 'FIN_COA_CRUD': 'Account', 'chartsOfAccounts': 'Account'
        };
        return labels[collectionName] || 'Record';
    };

    const visibleColumns = useMemo(() => (columns || []).filter(c => !c.isHidden && c.type !== 'array'), [columns]);

    const formatCell = (col, value) => {
        if (value === null || value === undefined || value === '') return '—';
        if (col.type === 'month' || (typeof value === 'string' && /^\d{4}-\d{2}$/.test(String(value).trim()))) {
            try {
                const s = String(value).trim();
                const d = new Date(s.length === 7 ? s + '-01' : s);
                if (!isNaN(d.getTime())) return d.toLocaleDateString('en-GB', { month: 'short', year: 'numeric' });
            } catch (e) {}
        }
        if (col.type === 'date' || (
            typeof value === 'string'
            && /^\d{4}-\d{2}-\d{2}/.test(value)
            && !/account|coa|ar_|ap_|bank/i.test(String(col.key || ''))
            && (() => { const y = parseInt(value.slice(0, 4), 10); return y >= 1970 && y <= 2100; })()
        )) {
            try {
                const d = new Date(value);
                if (!isNaN(d.getTime())) return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
            } catch (e) {}
        }
        if (col.type === 'number' || typeof value === 'number' || (typeof value === 'string' && value !== '' && !isNaN(Number(value)) && col.key && /amount|salary|pay|gross|net|tax|pension|basic|ot|allowance|deduction|indemnity/i.test(col.key))) {
            const n = Number(value);
            if (Number.isFinite(n)) return n.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
        }
        return String(value);
    };

    const periods = useMemo(() => {
        const set = new Set();
        const norm = (v) => {
            if (v == null || v === '') return null;
            const s = String(v).trim();
            if (/^\d{4}-\d{2}$/.test(s)) return s;
            if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 7);
            const d = new Date(s);
            if (!isNaN(d.getTime())) return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
            return s; // keep label like "July 2026" if present
        };
        dataMemo.forEach(r => {
            const a = norm(r.period); if (a) set.add(a);
            const b = norm(r.month); if (b) set.add(b);
            const c = norm(r.period_current); if (c) set.add(c);
            const d = norm(r.period_prior); if (d) set.add(d);
        });
        return ['All', ...Array.from(set).sort()];
    }, [dataMemo]);

    const filteredData = useMemo(() => {
        let rows = dataMemo;
        if (statusFilter !== 'All') {
            rows = rows.filter(r => String(r.status || '').toLowerCase() === statusFilter.toLowerCase());
        }
        if (periodFilter !== 'All') {
            rows = rows.filter(r => String(r.period || r.month || '') === periodFilter);
        }
        if (searchTerm) {
            const q = searchTerm.toLowerCase();
            rows = rows.filter(item =>
                visibleColumns.some(col => String(item[col.key] || '').toLowerCase().includes(q)) ||
                String(item.id || '').toLowerCase().includes(q) ||
                String(item.employee_name || '').toLowerCase().includes(q) ||
                String(item.partner_name || '').toLowerCase().includes(q) ||
                String(item.account_id || item.account_no || '').toLowerCase().includes(q)
            );
        }
        return rows;
    }, [dataMemo, searchTerm, visibleColumns, statusFilter, periodFilter]);

    const summaryCards = useMemo(() => {
        if (!isPayrollModule && !isFinanceModule) return null;
        const n = dataMemo.length;
        if (collectionName === 'FIN_PARTNERS_CRUD') {
            const customers = dataMemo.filter(r => String(r.partner_type||'').toLowerCase() === 'customer').length;
            const suppliers = dataMemo.filter(r => String(r.partner_type||'').toLowerCase() === 'supplier').length;
            const outstanding = dataMemo.reduce((s, r) => s + Number(r.outstanding_balance || 0), 0);
            const active = dataMemo.filter(r => String(r.status||'').toLowerCase() === 'active').length;
            return [
                { label: 'Partners', value: n, color: 'text-cyan-400' },
                { label: 'Active', value: active, color: 'text-emerald-400' },
                { label: 'Customers', value: customers, color: 'text-violet-400' },
                { label: 'Suppliers', value: suppliers, color: 'text-amber-400' },
                { label: 'Σ Outstanding', value: outstanding.toLocaleString(undefined,{minimumFractionDigits:2}), color: 'text-rose-400' }
            ];
        }
        if (collectionName === 'transactions') {
            const posted = dataMemo.filter(r => String(r.status||'').toLowerCase() === 'posted').length;
            const legAmt = (r) => {
                let d = Number(r.debit || 0), c = Number(r.credit || 0);
                if (!d && !c && Number(r.amount || 0) > 0) {
                    const t = String(r.type || '').toLowerCase();
                    if (t.startsWith('d')) d = Number(r.amount);
                    else c = Number(r.amount);
                }
                return { d, c };
            };
            const totalDr = dataMemo.reduce((s, r) => s + legAmt(r).d, 0);
            const totalCr = dataMemo.reduce((s, r) => s + legAmt(r).c, 0);
            const gap = Math.abs(totalDr - totalCr);
            return [
                { label: 'Txn Legs', value: n, color: 'text-cyan-400' },
                { label: 'Posted', value: posted, color: 'text-emerald-400' },
                { label: 'Σ Debit', value: totalDr.toLocaleString(undefined,{minimumFractionDigits:2}), color: 'text-emerald-400' },
                { label: 'Σ Credit', value: totalCr.toLocaleString(undefined,{minimumFractionDigits:2}), color: 'text-rose-400' },
                { label: 'Dr−Cr Gap', value: gap.toLocaleString(undefined,{minimumFractionDigits:2}), color: gap < 0.05 ? 'text-emerald-400' : 'text-rose-400' }
            ];
        }
        if (collectionName === 'dayJournals') {
            const posted = dataMemo.filter(r => String(r.status||'').toLowerCase() === 'posted').length;
            const verified = dataMemo.filter(r => String(r.status||'').toLowerCase() === 'verified').length;
            const totalDr = dataMemo.reduce((s, r) => s + Number(r.total_debit || r.amount || 0), 0);
            const totalCr = dataMemo.reduce((s, r) => s + Number(r.total_credit || r.amount || 0), 0);
            return [
                { label: 'Journals', value: n, color: 'text-cyan-400' },
                { label: 'Posted', value: posted, color: 'text-emerald-400' },
                { label: 'Verified', value: verified, color: 'text-violet-400' },
                { label: 'Σ Debit', value: totalDr.toLocaleString(undefined,{minimumFractionDigits:2}), color: 'text-emerald-400' },
                { label: 'Σ Credit', value: totalCr.toLocaleString(undefined,{minimumFractionDigits:2}), color: 'text-rose-400' }
            ];
        }
        if (!isPayrollModule) return null;
        if (collectionName === 'PAY_MASTER_CRUD') {
            const totalBasic = dataMemo.reduce((s, r) => s + Number(r.basic_salary || 0), 0);
            const active = dataMemo.filter(r => r.status === 'Active').length;
            return [
                { label: 'Staff on Master', value: n, color: 'text-cyan-400' },
                { label: 'Active', value: active, color: 'text-emerald-400' },
                { label: 'Σ Basic Salary', value: totalBasic.toLocaleString(undefined,{minimumFractionDigits:2}), color: 'text-amber-400' }
            ];
        }
        if (collectionName === 'PAY_FACTOR_MASTER_CRUD') {
            const row = dataMemo[0] || {};
            const pct = (v) => (Number(v) > 1 ? Number(v) : Number(v) * 100);
            return [
                { label: 'Factor Sets', value: n || 1, color: 'text-cyan-400' },
                { label: 'EE Pension %', value: pct(row.pension_employee || 0.07).toFixed(1) + '%', color: 'text-violet-400' },
                { label: 'ER Pension %', value: pct(row.pension_employer || 0.11).toFixed(1) + '%', color: 'text-amber-400' },
                { label: 'Work Hours / mo', value: row.working_hours || 160, color: 'text-emerald-400' },
                { label: 'OT Day ×', value: row.ot_day || 1.25, color: 'text-cyan-300' },
                { label: 'OT Night ×', value: row.ot_night || 1.5, color: 'text-rose-300' },
                { label: 'OT Weekend ×', value: row.ot_weekend || 2, color: 'text-amber-300' },
                { label: 'OT Holiday ×', value: row.ot_holiday || 2.5, color: 'text-fuchsia-300' },
            ];
        }
        if (collectionName === 'PAY_OVERTIME_CRUD') {
            const totalOt = dataMemo.reduce((s, r) => s + Number(r.total_ot_pay || 0), 0);
            const hrs = dataMemo.reduce((s, r) => s + Number(r.day_hrs||0)+Number(r.night_hrs||0)+Number(r.weekend_hrs||0)+Number(r.holiday_hrs||0), 0);
            return [
                { label: 'OT Records', value: n, color: 'text-cyan-400' },
                { label: 'Total Hours', value: hrs.toFixed(1), color: 'text-violet-400' },
                { label: 'Σ OT Pay', value: totalOt.toLocaleString(undefined,{minimumFractionDigits:2}), color: 'text-amber-400' }
            ];
        }
        if (collectionName === 'PAY_AD_CRUD') {
            const allw = dataMemo.filter(r => String(r.type).toLowerCase()==='allowance').reduce((s,r)=>s+Number(r.amount||0),0);
            const ded = dataMemo.filter(r => String(r.type).toLowerCase()==='deduction').reduce((s,r)=>s+Number(r.amount||0),0);
            return [
                { label: 'A/D Lines', value: n, color: 'text-cyan-400' },
                { label: 'Σ Allowances', value: allw.toLocaleString(undefined,{minimumFractionDigits:2}), color: 'text-emerald-400' },
                { label: 'Σ Deductions', value: ded.toLocaleString(undefined,{minimumFractionDigits:2}), color: 'text-rose-400' }
            ];
        }
        if (collectionName === 'PAY_PROCESS_CRUD') {
            const committed = dataMemo.filter(r => r.status === 'Committed').length;
            const gross = dataMemo.reduce((s,r)=>s+Number(r.gross_earnings||r.gross_amount||0),0);
            const net = dataMemo.reduce((s,r)=>s+Number(r.total_net||r.net_pay||0),0);
            const posted = dataMemo.filter(r => r.posted_to_finance).length;
            return [
                { label: 'Process Rows', value: n, color: 'text-cyan-400' },
                { label: 'Committed', value: committed, color: 'text-emerald-400' },
                { label: 'Posted to Finance', value: posted, color: 'text-violet-400' },
                { label: 'Σ Gross', value: gross.toLocaleString(undefined,{minimumFractionDigits:2}), color: 'text-amber-400' },
                { label: 'Σ Net', value: net.toLocaleString(undefined,{minimumFractionDigits:2}), color: 'text-white' }
            ];
        }
        return null;
    }, [dataMemo, collectionName, isPayrollModule]);

    const handleEdit = (record) => { setEditingRecord(record); setIsModalOpen(true); };

    const statusBadge = (status) => {
        const s = String(status || '');
        const cls = s === 'Committed' || s === 'Posted' || s === 'Active' || s === 'Approved'
            ? 'bg-emerald-500/20 text-emerald-300 border-emerald-500/40'
            : s === 'Draft' || s === 'Pending'
            ? 'bg-amber-500/20 text-amber-300 border-amber-500/40'
            : 'bg-white/10 text-gray-300 border-white/20';
        return <span className={`px-2 py-0.5 rounded-full text-[9px] font-black uppercase border ${cls}`}>{s || '—'}</span>;
    };

    return (
        <ContainerCard Icon='Table' glassClass={glassClass}>
            <div className="mb-6 border-l-4 border-cyan-500 pl-5 py-2 flex flex-wrap justify-between items-end gap-4">
                <div>
                    <h1 className="text-3xl font-black text-white uppercase italic tracking-tighter">{title || "Management"}</h1>
                    <p className="text-[10px] text-cyan-400 font-black uppercase tracking-[0.3em] opacity-80 mt-1">
                        Unity University · {filteredData.length} of {dataMemo.length} records
                    </p>
                </div>
                <div className="flex items-center gap-2">
                    {collectionName === 'PAY_PROCESS_CRUD' && typeof commitAllPayroll === 'function' && (
                        <button type="button" onClick={() => commitAllPayroll()} className="bg-violet-600 hover:bg-violet-500 text-white font-black py-2.5 px-5 rounded-xl text-[10px] uppercase tracking-widest shadow-lg">
                            Commit All → Finance
                        </button>
                    )}
                    <ExportButton data={filteredData} columns={columns} filename={collectionName} isFinancial={isPayrollModule || isFinanceModule} />
                </div>
            </div>

            {summaryCards && (
                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-3 mb-6">
                    {summaryCards.map((c, i) => (
                        <div key={i} className="rounded-xl border border-white/10 bg-black/30 px-4 py-3">
                            <div className="text-[9px] uppercase tracking-widest text-gray-500 font-bold">{c.label}</div>
                            <div className={`text-lg font-black mt-1 ${c.color}`}>{c.value}</div>
                        </div>
                    ))}
                </div>
            )}

            <div className="flex flex-wrap justify-between items-center gap-3 mb-6">
                <div className="flex flex-wrap items-center gap-2">
                {checkPermission('CAN_ADD_RECORD', allRoles) && (
                    <button onClick={() => {setEditingRecord({}); setIsModalOpen(true);}} className="bg-green-600 hover:bg-green-500 text-white font-black py-2.5 px-6 rounded-xl text-[10px] uppercase tracking-widest transition-all shadow-lg active:scale-95">
                        + Add {getAddLabel()}

                    </button>
                )}
                </div>
                <div className="flex flex-wrap items-center gap-2">
                    {isPayrollModule && (
                        <>
                            <UUSelect
                                value={statusFilter}
                                onChange={setStatusFilter}
                                options={(typeof statusOptions !== 'undefined' && statusOptions.length)
                                    ? statusOptions
                                    : ['All', 'Active', 'Draft', 'Pending', 'Committed', 'Approved', 'Inactive', 'Reconciled']}
                                allLabel="All statuses"
                                className="min-w-[240px] w-full max-w-[280px]"
                            />
                            <UUSelect
                                value={periodFilter}
                                onChange={setPeriodFilter}
                                options={(typeof periodOptions !== 'undefined' && periodOptions.length)
                                    ? periodOptions
                                    : ['All']}
                                allLabel="All periods"
                                className="min-w-[240px] w-full max-w-[280px]"
                            />
                        </>
                    )}
                    <div className="relative w-72">
                        <Icons.Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                        <input type="text" placeholder="Search name, ID, amount..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-black/40 border border-white/10 rounded-xl py-2.5 pl-10 text-xs text-white" />
                    </div>
                </div>
            </div>

<div className="rounded-xl border border-white/10 bg-black/20 overflow-x-auto text-[11px]">
                <table className="w-full text-left">
                    <thead className="bg-white/5 border-b border-white/10">
                        <tr className="text-cyan-500 font-black uppercase tracking-widest">
                            {visibleColumns.map(col => <th key={col.key} className="p-5">{col.label}</th>)}
                            <th className="p-5 text-center">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-white/5">
                        {filteredData.map(item => (
                            <tr key={item.id} className="hover:bg-white/[0.04]">
                                {visibleColumns.map(col => <td key={col.key} className="p-5 text-gray-300">{col.key === "status" ? statusBadge(item[col.key]) : formatCell(col, item[col.key])}</td>)}
                                <td className="p-5 text-center flex justify-center gap-3">
                                    <button onClick={() => handleEdit(item)} className="text-cyan-400"><Icons.Edit3 size={15}/></button>
                                    <button onClick={() => deleteRecord(collectionName, item.id)} className="text-red-500"><Icons.Trash2 size={15}/></button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            <Modal isOpen={isModalOpen} onClose={closeModal} title={`${editingRecord && editingRecord.id ? 'Edit' : 'New'} ${getAddLabel()}`}>
                <FormModal
                    collectionName={collectionName}
                    initialData={editingRecord}
                    onSave={closeModal}
                    onCancel={closeModal}
                />
            </Modal>
        </ContainerCard>
    );
};

