// ==========================================
// 2. TRIAL BALANCE DISPLAY COMPONENT
// ==========================================

export const FIN_TB_DISPLAY = ({ data, coaData, glassClass }) => {
    const [q, setQ] = useState('');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');
    const [typeFilter, setTypeFilter] = useState('All');
    const typeOptions = useMemo(() => ['All', 'Asset', 'Liability', 'Equity', 'Revenue', 'Expense'], []);
    // default false so material postings are visible even if still investigating balances
    const [onlyNonZero, setOnlyNonZero] = useState(true); // TB: only accounts with Single TX / Journal amounts
    /** net = one side per account (standard TB); gross = show both period Dr and Cr columns */
    const [tbMode, setTbMode] = useState('net');

    const isValidCode = (code) => /^\d{4}-\d{2}-\d{2}$/.test(String(code || '').trim());

    // Always merge Single-TX style sources so TB matches Single Transactions
    const txInput = useMemo(() => {
        const base = Array.isArray(data) ? data : [];
        let mat = [];
        try {
            mat = JSON.parse(localStorage.getItem('uu_shared_material_ledger_v1') || '[]');
            if (!Array.isArray(mat)) mat = [];
        } catch (e) { mat = []; }
        const ids = new Set(base.map((x) => x && x.id));
        const add = mat.filter((L) => L && L.id && !ids.has(L.id));
        // Normalize legs: ensure debit/credit numbers (Single TX may display amount only)
        return [...add, ...base].map((tx) => {
            if (!tx) return tx;
            let debit = Number(tx.debit);
            let credit = Number(tx.credit);
            if (!Number.isFinite(debit)) debit = 0;
            if (!Number.isFinite(credit)) credit = 0;
            if (!debit && !credit && Number(tx.amount) > 0) {
                const typ = String(tx.type || '').toLowerCase();
                if (typ.startsWith('d') || typ === 'dr') debit = Number(tx.amount);
                else if (typ.startsWith('c') || typ === 'cr') credit = Number(tx.amount);
                else if (String(tx.source || '').startsWith('MAT_') && String(tx.id || '').includes('-L1')) debit = Number(tx.amount);
                else if (String(tx.source || '').startsWith('MAT_') && String(tx.id || '').includes('-L2')) credit = Number(tx.amount);
            }
            const code = String(tx.account_code || tx.account_id || tx.account_no || '').replace(/^acc-/i, '').trim();
            return {
                ...tx,
                debit,
                credit,
                account_code: code || tx.account_code,
                account_id: code || tx.account_id,
                account_no: code || tx.account_no,
            };
        });
    }, [data]);

    const coaInput = useMemo(() => {
        if (Array.isArray(coaData) && coaData.length) return coaData;
        return [];
    }, [coaData]);

    const trialBalance = useMemo(() => {
        const rows = calculateTrialBalance(txInput, coaInput, startDate, endDate) || [];
        return rows
            .filter(r => isValidCode(r.account_no || r.account_code))
            .map((r) => {
                if (tbMode === 'gross') {
                    return {
                        ...r,
                        debit: Number(r.gross_debit != null ? r.gross_debit : r.debit) || 0,
                        credit: Number(r.gross_credit != null ? r.gross_credit : r.credit) || 0,
                    };
                }
                // net mode (default): already netted in calculateTrialBalance
                return r;
            });
    }, [txInput, coaInput, startDate, endDate, tbMode]);

    const types = useMemo(() => {
        const s = new Set();
        trialBalance.forEach(r => { if (r.type) s.add(r.type); });
        return ['All', ...Array.from(s).sort()];
    }, [trialBalance]);

    const filtered = useMemo(() => {
        const query = (q || '').toLowerCase().trim();
        return trialBalance.filter(r => {
            if (typeFilter !== 'All' && String(r.type || '') !== typeFilter) return false;
            if (onlyNonZero && !(Number(r.debit) > 0 || Number(r.credit) > 0)) return false;
            if (!query) return true;
            return (
                String(r.name || '').toLowerCase().includes(query) ||
                String(r.account_no || '').toLowerCase().includes(query) ||
                String(r.type || '').toLowerCase().includes(query) ||
                String(r.group || '').toLowerCase().includes(query)
            );
        }).sort((a, b) => String(a.account_no).localeCompare(String(b.account_no), undefined, { numeric: true }));
    }, [trialBalance, q, typeFilter, onlyNonZero]);

    // Full-book totals (match GL) — independent of search / non-zero filter
    const bookDebit = trialBalance.reduce((s, r) => s + parseFloat(r.debit || 0), 0);
    const bookCredit = trialBalance.reduce((s, r) => s + parseFloat(r.credit || 0), 0);
    const totalDebit = onlyNonZero || q || typeFilter !== 'All'
        ? filtered.reduce((s, r) => s + parseFloat(r.debit || 0), 0)
        : bookDebit;
    const totalCredit = onlyNonZero || q || typeFilter !== 'All'
        ? filtered.reduce((s, r) => s + parseFloat(r.credit || 0), 0)
        : bookCredit;
    const balanced = Math.abs(bookDebit - bookCredit) < 0.05;

    const fmt = (n) => Number(n || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });

    const tbExportCols = [
        { key: 'account_no', label: 'Acc No' },
        { key: 'name', label: 'Account Designation' },
        { key: 'type', label: 'Type' },
        { key: 'group', label: 'Group' },
        { key: 'debit', label: 'Debit Balance', type: 'number' },
        { key: 'credit', label: 'Credit Balance', type: 'number' },
    ];
    const tbExportRows = useMemo(() => {
        const rows = filtered.map(r => ({
            account_no: r.account_no || '',
            name: r.name || '',
            type: r.type || '',
            group: r.group || r.category || '',
            debit: Number(r.debit || 0),
            credit: Number(r.credit || 0),
        }));
        if (rows.length) {
            rows.push({ account_no: '', name: 'TOTAL', type: '', group: '', debit: totalDebit, credit: totalCredit });
        }
        return rows;
    }, [filtered, totalDebit, totalCredit]);
    const tbChartRef = useRef(null);

    return (
        <div className="space-y-6 animate-in fade-in duration-500" ref={tbChartRef}>
            <div className={`p-6 rounded-[2rem] ${glassClass} border border-cyan-500/30 bg-gradient-to-br from-cyan-950/40 to-black/40 shadow-2xl`}>
                <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                    <div className="flex items-center gap-3">
                        <div className="p-3 rounded-2xl bg-yellow-500/15 border border-yellow-400/25">
                            <Icons.Scale className="w-6 h-6 text-yellow-400" />
                        </div>
                        <div>
                            <h2 className="text-2xl font-black text-white italic uppercase tracking-tight">Trial Balance</h2>
                            <p className="text-[10px] text-cyan-300/80 font-black uppercase tracking-[0.2em]">
                                Gross activity · Single + Journal + Payroll · ####-##-## · {startDate || endDate ? 'Period filter on' : 'All dates'}
                            </p>
                        </div>
                    </div>
                    <div className="flex flex-wrap gap-2 items-center">
                        <span className={`text-[10px] px-3 py-1.5 rounded-full font-black uppercase border ${balanced ? 'bg-emerald-500/15 text-emerald-400 border-emerald-500/30' : 'bg-rose-500/15 text-rose-400 border-rose-500/30'}`}>
                            {balanced ? 'In balance' : 'Out of balance'}
                        </span>
                        <ExportButton
                            data={tbExportRows}
                            columns={tbExportCols}
                            filename="Unity_Trial_Balance"
                            chartRef={tbChartRef}
                            isFinancial={true}
                        />
                    </div>
                </div>

                <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mt-6">
                    <div className="p-4 rounded-2xl bg-black/40 border border-white/10">
                        <span className="text-[9px] text-gray-500 uppercase font-black block">Accounts</span>
                        <span className="text-xl font-black text-white font-mono">{filtered.length}</span>
                        <span className="text-[9px] text-gray-600 ml-1">/ {trialBalance.length}</span>
                    </div>
                    <div className="p-4 rounded-2xl bg-black/40 border border-emerald-500/20">
                        <span className="text-[9px] text-gray-500 uppercase font-black block">Total Debit (Books)</span>
                        <span className="text-lg font-black text-emerald-400 font-mono">{fmt(bookDebit)}</span>
                    </div>
                    <div className="p-4 rounded-2xl bg-black/40 border border-rose-500/20">
                        <span className="text-[9px] text-gray-500 uppercase font-black block">Total Credit (Books)</span>
                        <span className="text-lg font-black text-rose-400 font-mono">{fmt(bookCredit)}</span>
                    </div>
                    <div className="p-4 rounded-2xl bg-black/40 border border-white/10">
                        <span className="text-[9px] text-gray-500 uppercase font-black block">Difference</span>
                        <span className={`text-lg font-black font-mono ${balanced ? 'text-emerald-400' : 'text-amber-400'}`}>{fmt(Math.abs(totalDebit - totalCredit))}</span>
                    </div>
                </div>
            </div>

            <div className={`rounded-[1.75rem] ${glassClass} border border-white/10 bg-slate-950/95 overflow-visible`}>
                <div className="p-4 sm:p-6 space-y-4">
                    <p className="text-[10px] font-black uppercase tracking-widest text-cyan-400/90">Filters · Trial Balance</p>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        <div className="min-w-0 space-y-1.5">
                            <label className="block text-[10px] font-black uppercase tracking-wider text-gray-400">Search accounts</label>
                            <div className="relative">
                                <Icons.Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-cyan-400/70 pointer-events-none" />
                                <input
                                    type="text"
                                    placeholder="Code or designation…"
                                    className="w-full max-w-full box-border pl-10 pr-3 py-2.5 rounded-xl bg-black/70 border border-cyan-500/30 text-white text-sm outline-none focus:ring-2 focus:ring-cyan-500/40 min-h-[44px]"
                                    value={q}
                                    onChange={e => setQ(e.target.value)}
                                />
                            </div>
                        </div>
                        <div className="min-w-0 space-y-1.5">
                            <label className="block text-[10px] font-black uppercase tracking-wider text-gray-400">Account type</label>
                            <UUSelect
                                value={typeFilter}
                                onChange={setTypeFilter}
                                options={typeOptions}
                                allLabel="All account types"
                                className="w-full max-w-full block"
                            />
                        </div>
                        <div className="min-w-0 space-y-1.5">
                            <label className="block text-[10px] font-black uppercase tracking-wider text-gray-400">Balance mode</label>
                            <UUSelect
                                value={tbMode}
                                onChange={setTbMode}
                                options={[
                                    { value: 'net', label: 'Net (standard TB)' },
                                    { value: 'gross', label: 'Gross (Dr + Cr columns)' },
                                ]}
                                allLabel="Net (standard TB)"
                                className="w-full max-w-full block"
                            />
                        </div>
                        <div className="min-w-0 space-y-1.5 flex flex-col justify-end">
                            <label className="flex items-center gap-2 py-2.5 px-3 rounded-xl bg-black/50 border border-white/15 text-[11px] text-gray-200 font-bold uppercase cursor-pointer min-h-[44px]">
                                <input type="checkbox" checked={onlyNonZero} onChange={e => setOnlyNonZero(e.target.checked)} className="accent-cyan-500 w-4 h-4 shrink-0" />
                                Non-zero only
                            </label>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 pt-1 border-t border-white/10">
                        <div className="min-w-0 space-y-1.5">
                            <label className="block text-[10px] font-black uppercase tracking-wider text-gray-400">Period from</label>
                            <input
                                type="date"
                                value={startDate}
                                onChange={e => setStartDate(e.target.value)}
                                className="w-full max-w-full box-border py-2.5 px-3 rounded-xl bg-black/70 border border-white/20 text-white text-sm min-h-[44px] outline-none focus:ring-2 focus:ring-cyan-500/30 [color-scheme:dark]"
                            />
                        </div>
                        <div className="min-w-0 space-y-1.5">
                            <label className="block text-[10px] font-black uppercase tracking-wider text-gray-400">Period to</label>
                            <input
                                type="date"
                                value={endDate}
                                onChange={e => setEndDate(e.target.value)}
                                className="w-full max-w-full box-border py-2.5 px-3 rounded-xl bg-black/70 border border-white/20 text-white text-sm min-h-[44px] outline-none focus:ring-2 focus:ring-cyan-500/30 [color-scheme:dark]"
                            />
                        </div>
                        <div className="min-w-0 flex items-end">
                            <button
                                type="button"
                                onClick={() => {
                                    const now = new Date();
                                    const y = now.getFullYear();
                                    const m = String(now.getMonth() + 1).padStart(2, '0');
                                    setStartDate(`${y}-${m}-01`);
                                    setEndDate(`${y}-${m}-${String(new Date(y, now.getMonth() + 1, 0).getDate()).padStart(2, '0')}`);
                                }}
                                className="w-full py-2.5 rounded-xl text-[10px] font-black uppercase bg-cyan-500/15 text-cyan-300 border border-cyan-500/25 min-h-[44px] hover:bg-cyan-500/25"
                            >
                                This month
                            </button>
                        </div>
                        <div className="min-w-0 flex items-end">
                            {(q || typeFilter !== 'All' || startDate || endDate || !onlyNonZero || tbMode !== 'net') ? (
                                <button
                                    type="button"
                                    onClick={() => { setQ(''); setTypeFilter('All'); setStartDate(''); setEndDate(''); setOnlyNonZero(true); setTbMode('net'); }}
                                    className="w-full py-2.5 rounded-xl text-[10px] font-black uppercase bg-rose-500/15 text-rose-300 border border-rose-500/25 min-h-[44px] hover:bg-rose-500/25"
                                >
                                    Clear filters
                                </button>
                            ) : (
                                <div className="w-full min-h-[44px]" />
                            )}
                        </div>
                    </div>

                    {(startDate || endDate) && (
                        <p className="text-[10px] text-cyan-300/70 font-bold m-0">
                            Period: {startDate || '…'} → {endDate || '…'} · Single TX + Journal in range
                        </p>
                    )}
                </div>
            </div>

            <div className="overflow-hidden rounded-[1.75rem] border border-white/10 bg-black/50 shadow-2xl">
                <div className="uu-table-scroll overflow-x-auto max-h-[65vh] custom-scrollbar">
                    <table className="w-full text-left border-collapse min-w-[720px]">
                        <thead className="sticky top-0 z-10 bg-slate-950/95 backdrop-blur border-b border-white/10 text-[10px] uppercase font-black tracking-widest text-cyan-400">
                            <tr>
                                <th className="p-4 w-36">Acc No</th>
                                <th className="p-4">Account Designation</th>
                                <th className="p-4 w-28">Type</th>
                                <th className="p-4 text-right w-36">Debit Balance</th>
                                <th className="p-4 text-right w-36">Credit Balance</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-white/5">
                            {filtered.length > 0 ? filtered.map((row, i) => (
                                <tr key={`${row.account_no}-${i}`} className="hover:bg-cyan-500/[0.04] transition-colors group">
                                    <td className="p-3.5 text-[12px] font-mono text-cyan-300 font-bold whitespace-nowrap">{row.account_no}</td>
                                    <td className="p-3.5 text-sm text-white font-semibold group-hover:text-cyan-50">{row.name}</td>
                                    <td className="p-3.5">
                                        <span className="text-[9px] px-2 py-0.5 rounded-full bg-white/5 border border-white/10 text-gray-400 uppercase font-black">{row.type || '—'}</span>
                                    </td>
                                    <td className="p-3.5 text-right font-mono text-[12px] text-emerald-400">
                                        {Number(row.debit) > 0 ? fmt(row.debit) : <span className="text-gray-600">—</span>}
                                    </td>
                                    <td className="p-3.5 text-right font-mono text-[12px] text-rose-400">
                                        {Number(row.credit) > 0 ? fmt(row.credit) : <span className="text-gray-600">—</span>}
                                    </td>
                                </tr>
                            )) : (
                                <tr>
                                    <td colSpan="5" className="p-12 text-center text-xs text-gray-500 italic">No valid ####-##-## accounts match your filters.</td>
                                </tr>
                            )}
                        </tbody>
                        <tfoot className="bg-cyan-950/40 text-white font-black border-t border-cyan-500/25 sticky bottom-0">
                            <tr>
                                <td colSpan="3" className="p-4 text-[11px] uppercase tracking-widest text-cyan-300">Trial balance totals</td>
                                <td className="p-4 text-right text-base text-emerald-400 font-mono">{fmt(totalDebit)}</td>
                                <td className="p-4 text-right text-base text-rose-400 font-mono">{fmt(totalCredit)}</td>
                            </tr>
                        </tfoot>
                    </table>
                </div>
            </div>
            <p className="text-center text-[9px] text-gray-600 uppercase tracking-[0.4em] pb-2">Unity Finance · COA keys ####-##-## only · Engine v5</p>
        </div>
    );
};



// ==========================================
// 3. GENERAL LEDGER DISPLAY COMPONENT
// ==========================================
export const FIN_GL_DISPLAY = ({ data, coaData, glassClass }) => {
    const [selectedAccount, setSelectedAccount] = useState('All');
    const [searchTerm, setSearchTerm] = useState('');
    const [accountQuery, setAccountQuery] = useState('');
    const [accountPickerOpen, setAccountPickerOpen] = useState(false);
    const [accountMenuBox, setAccountMenuBox] = useState(null);
    const accountBtnRef = useRef(null);
    const accountPickerRef = useRef(null);
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');
    const [typeFilter, setTypeFilter] = useState('All');
    const [expandedAccounts, setExpandedAccounts] = useState({});
    const [sortMode, setSortMode] = useState('code'); // code | name | balance
    const typeOptions = useMemo(() => ['All', 'Asset', 'Liability', 'Equity', 'Revenue', 'Expense'], []);
    const sortOptions = useMemo(() => [
        { value: 'code', label: 'Sort by account code' },
        { value: 'name', label: 'Sort by account name' },
        { value: 'balance', label: 'Sort by balance' },
    ], []);

    useEffect(() => {
        if (!accountPickerOpen) {
            setAccountMenuBox(null);
            return undefined;
        }
        const place = () => {
            const el = accountBtnRef.current;
            if (!el) return;
            const r = el.getBoundingClientRect();
            const gap = 4;
            const maxH = 360;
            const spaceBelow = window.innerHeight - r.bottom - gap;
            const spaceAbove = r.top - gap;
            const openUp = spaceBelow < 180 && spaceAbove > spaceBelow;
            const height = Math.min(maxH, Math.max(160, openUp ? spaceAbove : spaceBelow));
            const width = Math.min(Math.max(r.width, 280), Math.min(window.innerWidth - 16, 560));
            let left = r.left;
            if (left + width > window.innerWidth - 8) left = Math.max(8, window.innerWidth - width - 8);
            if (left < 8) left = 8;
            const top = openUp ? Math.max(8, r.top - gap - height) : r.bottom + gap;
            setAccountMenuBox({ top, left, width, maxHeight: height });
        };
        place();
        const onDoc = (e) => {
            if (accountBtnRef.current && accountBtnRef.current.contains(e.target)) return;
            if (e.target && e.target.closest && e.target.closest('[data-uu-gl-account-menu]')) return;
            setAccountPickerOpen(false);
        };
        document.addEventListener('mousedown', onDoc);
        document.addEventListener('touchstart', onDoc);
        window.addEventListener('resize', place);
        window.addEventListener('scroll', place, true);
        return () => {
            document.removeEventListener('mousedown', onDoc);
            document.removeEventListener('touchstart', onDoc);
            window.removeEventListener('resize', place);
            window.removeEventListener('scroll', place, true);
        };
    }, [accountPickerOpen]);

    const isValidCode = (code) => /^\d{4}-\d{2}-\d{2}$/.test(String(code || '').trim());
    const cleanCode = (id) => String(id || '').replace(/^acc-/i, '').trim();

    const trialBalanceRows = useMemo(() => {
        const rows = calculateTrialBalance(data, coaData, startDate, endDate) || [];
        return rows.filter(r => isValidCode(r.account_no || r.account_code));
    }, [data, coaData, startDate, endDate]);

    const isRealTx = (tx) => {
        if (!tx || tx.isSystemFrame) return false;
        const ref = String(tx.reference || '');
        if (ref.startsWith('MOCK-COA-') || ref === 'TB-SEED') return false;
        const id = String(tx.id || '');
        if (id.startsWith('SYS-')) return false;
        return true;
    };

    const primaryLeg = (tx) => {
        const date = tx.date || tx.posting_date || tx.createdAt || tx.transactionDate || new Date().toISOString().split('T')[0];
        const narrative = String(tx.description || tx.narration || tx.reference || 'Journal entry');
        const partner = tx.partner_name || tx.entity || tx.partner || '';
        const ref = tx.reference || tx.id || tx.ref || '';
        const status = tx.status || 'Posted';
        const code = cleanCode(tx.account_id || tx.account_code || tx.account_no || tx.accountCode || '');
        if (!isValidCode(code)) return null;
        let debit = Number(tx.debit || 0);
        let credit = Number(tx.credit || 0);
        if ((!debit && !credit) && Number(tx.amount || 0) > 0) {
            const t = String(tx.type || '').toLowerCase();
            if (t.startsWith('d') || t === 'dr') debit = Number(tx.amount);
            else credit = Number(tx.amount);
        }
        if (!Number.isFinite(debit)) debit = 0;
        if (!Number.isFinite(credit)) credit = 0;
        if (debit <= 0 && credit <= 0) return null;
        return { account_code: code, account_name: tx.account_name || tx.accountName || code, date, narrative, partner, ref, status, debit, credit };
    };

    const isDebitNormalType = (type) => {
        const t = String(type || '').toLowerCase();
        return t.includes('asset') || t.includes('expense') || t.includes('cost') || t.includes('loss') || t.includes('cash');
    };

    const ledgerData = useMemo(() => {
        const accounts = {};
        trialBalanceRows.forEach(row => {
            const code = cleanCode(row.account_no || row.account_code);
            if (!isValidCode(code)) return;
            accounts[code] = {
                meta: {
                    account_no: code,
                    name: row.name || row.description || row.desc || code,
                    type: row.type || row.group || 'General',
                    group: row.group || row.category || '',
                    tbDebit: Number(row.debit || 0),
                    tbCredit: Number(row.credit || 0),
                },
                entries: [],
                runningBalance: 0,
                totalDebit: 0,
                totalCredit: 0,
            };
        });

        const raw = Array.isArray(data) ? data : [];
        const sorted = [...raw].filter(isRealTx).filter(tx => {
            const txDate = tx.date || tx.posting_date || tx.createdAt || tx.transactionDate;
            if (!txDate) return true;
            const time = new Date(txDate).getTime();
            if (startDate && time < new Date(startDate).getTime()) return false;
            if (endDate && time > new Date(endDate).setHours(23, 59, 59, 999)) return false;
            return true;
        }).sort((a, b) => new Date(a.date || a.posting_date || 0) - new Date(b.date || b.posting_date || 0));

        sorted.forEach(tx => {
            const leg = primaryLeg(tx);
            if (!leg || !accounts[leg.account_code]) return;
            const acc = accounts[leg.account_code];
            const normalDr = isDebitNormalType(acc.meta.type);
            if (leg.debit > 0) {
                acc.runningBalance += normalDr ? leg.debit : -leg.debit;
                acc.totalDebit += leg.debit;
            }
            if (leg.credit > 0) {
                acc.runningBalance += normalDr ? -leg.credit : leg.credit;
                acc.totalCredit += leg.credit;
            }
            acc.entries.push({
                date: leg.date,
                description: leg.narrative,
                narration: leg.narrative,
                partner: leg.partner,
                reference: leg.ref,
                status: leg.status,
                account_code: leg.account_code,
                account_name: acc.meta.name,
                debit: leg.debit,
                credit: leg.credit,
                balanceAfter: acc.runningBalance,
            });
        });

        Object.keys(accounts).forEach(code => {
            const a = accounts[code];
            if (a.entries.length === 0) {
                a.totalDebit = a.meta.tbDebit;
                a.totalCredit = a.meta.tbCredit;
                a.runningBalance = isDebitNormalType(a.meta.type)
                    ? (a.meta.tbDebit - a.meta.tbCredit)
                    : (a.meta.tbCredit - a.meta.tbDebit);
            }
        });
        return accounts;
    }, [data, trialBalanceRows, startDate, endDate]);

    const accountKeys = useMemo(() => {
        let keys = Object.keys(ledgerData);
        // Default view: accounts with real lines or non-zero TB (avoids 900+ empty rows)
        keys = keys.filter(k => {
            const a = ledgerData[k];
            if (!a) return false;
            if (a.entries && a.entries.length > 0) return true;
            if (Number(a.meta.tbDebit || 0) > 0 || Number(a.meta.tbCredit || 0) > 0) return true;
            return false;
        });
        if (typeFilter !== 'All') {
            keys = keys.filter(k => String(ledgerData[k].meta.type || '').toLowerCase() === typeFilter.toLowerCase());
        }
        if (selectedAccount !== 'All') {
            keys = keys.filter(k => k === selectedAccount);
        }
        // Global search: account code, name, or any entry narrative/partner/ref
        const q = searchTerm.trim().toLowerCase();
        if (q) {
            keys = keys.filter(k => {
                const acc = ledgerData[k];
                const metaHit =
                    String(acc.meta.account_no || '').toLowerCase().includes(q) ||
                    String(acc.meta.name || '').toLowerCase().includes(q) ||
                    String(acc.meta.type || '').toLowerCase().includes(q);
                if (metaHit) return true;
                return acc.entries.some(e =>
                    String(e.description || e.narration || '').toLowerCase().includes(q) ||
                    String(e.partner || '').toLowerCase().includes(q) ||
                    String(e.reference || '').toLowerCase().includes(q) ||
                    String(e.account_code || '').toLowerCase().includes(q)
                );
            });
        }
        keys.sort((a, b) => {
            const A = ledgerData[a], B = ledgerData[b];
            if (sortMode === 'name') return String(A.meta.name).localeCompare(String(B.meta.name));
            if (sortMode === 'balance') return Math.abs(B.runningBalance) - Math.abs(A.runningBalance);
            return String(A.meta.account_no || a).localeCompare(String(B.meta.account_no || b), undefined, { numeric: true });
        });
        return keys;
    }, [ledgerData, selectedAccount, typeFilter, searchTerm, sortMode]);

    const accountTypes = useMemo(() => {
        const set = new Set();
        Object.values(ledgerData).forEach(a => { if (a.meta.type) set.add(a.meta.type); });
        return ['All', ...Array.from(set).sort()];
    }, [ledgerData]);

    const totals = useMemo(() => {
        let dr = 0, cr = 0, accountsWithActivity = 0;
        accountKeys.forEach(k => {
            const a = ledgerData[k];
            if (a.entries.length) accountsWithActivity += 1;
            dr += a.totalDebit;
            cr += a.totalCredit;
        });
        return { dr, cr, accountsWithActivity, accountCount: accountKeys.length };
    }, [accountKeys, ledgerData]);

    const toggleExpand = (key) => {
        setExpandedAccounts(prev => ({ ...prev, [key]: !prev[key] }));
    };

    const expandAll = () => {
        const next = {};
        accountKeys.forEach(k => { next[k] = true; });
        setExpandedAccounts(next);
    };

    const collapseAll = () => setExpandedAccounts({});

    const glExportCols = [
        { key: 'account_no', label: 'Account Code' },
        { key: 'name', label: 'Account Name' },
        { key: 'type', label: 'Type' },
        { key: 'date', label: 'Date', type: 'date' },
        { key: 'reference', label: 'Reference' },
        { key: 'partner', label: 'Partner' },
        { key: 'narration', label: 'Narration' },
        { key: 'debit', label: 'Debit', type: 'number' },
        { key: 'credit', label: 'Credit', type: 'number' },
        { key: 'balance', label: 'Balance', type: 'number' },
    ];
    const glExportRows = useMemo(() => {
        const out = [];
        accountKeys.forEach(k => {
            const acc = ledgerData[k];
            if (!acc) return;
            const q = searchTerm.trim().toLowerCase();
            const entries = q
                ? (acc.entries || []).filter(e =>
                    String(e.description || '').toLowerCase().includes(q) ||
                    String(e.partner || '').toLowerCase().includes(q) ||
                    String(e.reference || '').toLowerCase().includes(q))
                : (acc.entries || []);
            entries.forEach(e => {
                out.push({
                    account_no: acc.meta.account_no || '',
                    name: acc.meta.name || '',
                    type: acc.meta.type || '',
                    date: e.date || '',
                    reference: e.reference || '',
                    partner: e.partner || '',
                    narration: String(e.description || e.narration || '').replace(/\s+/g, ' ').trim(),
                    debit: Number(e.debit || 0),
                    credit: Number(e.credit || 0),
                    balance: Number(e.balanceAfter || 0),
                });
            });
        });
        return out;
    }, [accountKeys, ledgerData, searchTerm]);
    const glChartRef = useRef(null);

    const fmt = (n) => Number(n || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });

    return (
        <div className="space-y-6 animate-in fade-in duration-500" ref={glChartRef}>
            {/* Header */}
            <div className={`p-6 rounded-[2rem] ${glassClass} border border-cyan-500/30 bg-gradient-to-br from-cyan-950/40 to-black/40 shadow-2xl`}>
                <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                    <div>
                        <h2 className="text-2xl md:text-3xl font-black text-white italic uppercase tracking-tight flex items-center gap-3">
                            <span className="p-2 rounded-2xl bg-cyan-500/20 border border-cyan-400/30">
                                <Icons.BookOpen className="w-6 h-6 text-cyan-400" />
                            </span>
                            General Ledger
                        </h2>
                        <p className="text-[11px] text-cyan-300/80 font-bold uppercase tracking-[0.25em] mt-1">
                            Unity University · Account activity with narratives &amp; running balances
                        </p>
                    </div>
                    <div className="flex flex-wrap gap-2">
                        <button onClick={expandAll} className="px-4 py-2 rounded-xl text-[10px] font-black uppercase bg-white/5 border border-white/10 text-white hover:bg-white/10">Expand All</button>
                        <button onClick={collapseAll} className="px-4 py-2 rounded-xl text-[10px] font-black uppercase bg-white/5 border border-white/10 text-white hover:bg-white/10">Collapse</button>
                        <ExportButton
                            data={glExportRows}
                            columns={glExportCols}
                            filename="Unity_General_Ledger"
                            chartRef={glChartRef}
                            isFinancial={true}
                        />
                    </div>
                </div>

                {/* KPI strip */}
                <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mt-6">
                    <div className="p-4 rounded-2xl bg-black/40 border border-white/10">
                        <span className="text-[9px] text-gray-500 uppercase font-black block">Accounts Shown</span>
                        <span className="text-xl font-black text-white font-mono">{totals.accountCount}</span>
                    </div>
                    <div className="p-4 rounded-2xl bg-black/40 border border-white/10">
                        <span className="text-[9px] text-gray-500 uppercase font-black block">With Activity</span>
                        <span className="text-xl font-black text-cyan-400 font-mono">{totals.accountsWithActivity}</span>
                    </div>
                    <div className="p-4 rounded-2xl bg-black/40 border border-emerald-500/20">
                        <span className="text-[9px] text-gray-500 uppercase font-black block">Total Debits</span>
                        <span className="text-lg font-black text-emerald-400 font-mono">{fmt(totals.dr)}</span>
                    </div>
                    <div className="p-4 rounded-2xl bg-black/40 border border-rose-500/20">
                        <span className="text-[9px] text-gray-500 uppercase font-black block">Total Credits</span>
                        <span className="text-lg font-black text-rose-400 font-mono">{fmt(totals.cr)}</span>
                    </div>
                </div>
            </div>

            {/* Filters — contained inside card, no overflow outside */}
            <div className={`rounded-[1.75rem] ${glassClass} border border-white/10 bg-slate-950/95 overflow-visible`}>
                <div className="p-4 sm:p-6 space-y-4">
                    <p className="text-[10px] font-black uppercase tracking-widest text-cyan-400/90">Filters · General Ledger</p>

                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                        <div className="min-w-0 space-y-1.5 sm:col-span-2 lg:col-span-1">
                            <label className="block text-[10px] font-black uppercase tracking-wider text-gray-400">Search ledger</label>
                            <div className="relative">
                                <Icons.Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-cyan-400/70 pointer-events-none" />
                                <input
                                    type="text"
                                    placeholder="Code, account, narration, partner…"
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                    className="w-full max-w-full box-border pl-10 pr-3 py-2.5 rounded-xl bg-black/70 border border-cyan-500/30 text-white text-sm outline-none focus:ring-2 focus:ring-cyan-500/40 min-h-[44px]"
                                />
                            </div>
                        </div>
                        <div className="min-w-0 space-y-1.5">
                            <label className="block text-[10px] font-black uppercase tracking-wider text-gray-400">Account type</label>
                            <UUSelect
                                value={typeFilter}
                                onChange={setTypeFilter}
                                options={(typeof typeOptions !== 'undefined' && typeOptions?.length) ? typeOptions : ['All', 'Asset', 'Liability', 'Equity', 'Revenue', 'Expense']}
                                allLabel="All account types"
                                className="w-full max-w-full block"
                            />
                        </div>
                        <div className="min-w-0 space-y-1.5">
                            <label className="block text-[10px] font-black uppercase tracking-wider text-gray-400">Sort</label>
                            <UUSelect
                                value={sortMode}
                                onChange={setSortMode}
                                options={sortOptions}
                                allLabel="Sort mode"
                                className="w-full max-w-full block"
                            />
                        </div>
                    </div>

                    <div className="min-w-0 space-y-1.5 relative" ref={accountPickerRef}>
                        <label className="block text-[10px] font-black uppercase tracking-wider text-gray-400">Account</label>
                        <button
                            type="button"
                            ref={accountBtnRef}
                            onClick={() => setAccountPickerOpen((o) => !o)}
                            className="w-full max-w-full box-border py-2.5 px-3 rounded-xl bg-black/70 border border-white/20 text-white text-sm outline-none flex items-center justify-between gap-2 hover:border-cyan-500/40 min-h-[44px]"
                        >
                            <span className="truncate text-left font-mono text-[12px] sm:text-sm">
                                {selectedAccount === 'All'
                                    ? `All Accounts (${Object.keys(ledgerData).length})`
                                    : `${ledgerData[selectedAccount]?.meta?.account_no || ''} — ${ledgerData[selectedAccount]?.meta?.name || selectedAccount}`}
                            </span>
                            <Icons.ChevronDown className={`w-4 h-4 shrink-0 text-cyan-400 transition-transform ${accountPickerOpen ? 'rotate-180' : ''}`} />
                        </button>
                        {accountPickerOpen && accountMenuBox && createPortal(
                            <div
                                data-uu-gl-account-menu="1"
                                className="overflow-hidden rounded-xl border border-cyan-500/40 bg-slate-950 shadow-2xl shadow-black/80"
                                style={{
                                    position: 'fixed',
                                    top: accountMenuBox.top,
                                    left: accountMenuBox.left,
                                    width: accountMenuBox.width,
                                    maxHeight: accountMenuBox.maxHeight,
                                    zIndex: 2147483646,
                                }}
                            >
                                <div className="p-2 border-b border-white/10 bg-slate-950 sticky top-0 z-10">
                                    <input
                                        autoFocus
                                        type="text"
                                        placeholder="Filter by code or name…"
                                        value={accountQuery}
                                        onChange={(e) => setAccountQuery(e.target.value)}
                                        className="w-full max-w-full box-border py-2 px-3 rounded-lg bg-black/70 border border-white/10 text-white text-sm outline-none focus:ring-1 focus:ring-cyan-500/50"
                                    />
                                </div>
                                <div className="overflow-y-auto custom-scrollbar" style={{ maxHeight: Math.max(120, (accountMenuBox.maxHeight || 320) - 56) }}>
                                    <button
                                        type="button"
                                        className={`w-full text-left px-3 py-2.5 text-sm hover:bg-cyan-500/15 border-b border-white/5 ${selectedAccount === 'All' ? 'bg-cyan-500/20 text-cyan-300' : 'text-gray-300'}`}
                                        onClick={() => { setSelectedAccount('All'); setAccountPickerOpen(false); setAccountQuery(''); }}
                                    >
                                        <span className="font-black uppercase tracking-wider text-[11px]">All Accounts</span>
                                        <span className="text-gray-500 ml-2">({Object.keys(ledgerData).length})</span>
                                    </button>
                                    {Object.keys(ledgerData)
                                        .filter((k) => {
                                            const q = accountQuery.trim().toLowerCase();
                                            if (!q) return true;
                                            const m = ledgerData[k].meta;
                                            return String(m.account_no || '').toLowerCase().includes(q)
                                                || String(m.name || '').toLowerCase().includes(q)
                                                || String(m.type || '').toLowerCase().includes(q);
                                        })
                                        .sort((a, b) => String(ledgerData[a].meta.account_no).localeCompare(String(ledgerData[b].meta.account_no), undefined, { numeric: true }))
                                        .slice(0, 400)
                                        .map((k) => {
                                            const m = ledgerData[k].meta;
                                            const active = selectedAccount === k;
                                            return (
                                                <button
                                                    key={k}
                                                    type="button"
                                                    className={`w-full text-left px-3 py-2.5 text-sm hover:bg-cyan-500/15 border-b border-white/5 flex items-center gap-2 ${active ? 'bg-cyan-500/20 text-cyan-200' : 'text-gray-300'}`}
                                                    onClick={() => { setSelectedAccount(k); setAccountPickerOpen(false); setAccountQuery(''); }}
                                                >
                                                    <span className="font-mono text-cyan-400 font-bold shrink-0 w-28">{m.account_no || '—'}</span>
                                                    <span className="text-gray-200 truncate flex-1">{m.name || '—'}</span>
                                                    <span className="text-[10px] text-gray-500 shrink-0">{m.type || ''}</span>
                                                </button>
                                            );
                                        })}
                                </div>
                            </div>,
                            document.body
                        )}
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 pt-1 border-t border-white/10">
                        <div className="min-w-0 space-y-1.5">
                            <label className="block text-[10px] font-black uppercase tracking-wider text-gray-400">Period from</label>
                            <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full max-w-full box-border py-2.5 px-3 rounded-xl bg-black/70 border border-white/20 text-white text-sm min-h-[44px] outline-none focus:ring-2 focus:ring-cyan-500/30 [color-scheme:dark]" />
                        </div>
                        <div className="min-w-0 space-y-1.5">
                            <label className="block text-[10px] font-black uppercase tracking-wider text-gray-400">Period to</label>
                            <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full max-w-full box-border py-2.5 px-3 rounded-xl bg-black/70 border border-white/20 text-white text-sm min-h-[44px] outline-none focus:ring-2 focus:ring-cyan-500/30 [color-scheme:dark]" />
                        </div>
                        <div className="min-w-0 flex items-end">
                            <button
                                type="button"
                                onClick={() => {
                                    const now = new Date();
                                    const y = now.getFullYear();
                                    const m = String(now.getMonth() + 1).padStart(2, '0');
                                    setStartDate(`${y}-${m}-01`);
                                    setEndDate(`${y}-${m}-${String(new Date(y, now.getMonth() + 1, 0).getDate()).padStart(2, '0')}`);
                                }}
                                className="w-full py-2.5 rounded-xl text-[10px] font-black uppercase bg-cyan-500/15 text-cyan-300 border border-cyan-500/25 min-h-[44px] hover:bg-cyan-500/25"
                            >
                                This month
                            </button>
                        </div>
                        <div className="min-w-0 flex items-end gap-2">
                            {(searchTerm || selectedAccount !== 'All' || typeFilter !== 'All' || startDate || endDate) && (
                                <button
                                    type="button"
                                    onClick={() => { setSearchTerm(''); setSelectedAccount('All'); setTypeFilter('All'); setStartDate(''); setEndDate(''); setAccountQuery(''); }}
                                    className="flex-1 py-2.5 rounded-xl text-[10px] font-black uppercase bg-rose-500/15 text-rose-300 border border-rose-500/25 min-h-[44px] hover:bg-rose-500/25"
                                >
                                    Clear
                                </button>
                            )}
                            <span className="text-[10px] text-gray-500 font-mono py-2 whitespace-nowrap">
                                <span className="text-cyan-400 font-bold">{accountKeys.length}</span> acct
                            </span>
                        </div>
                    </div>

                    {(startDate || endDate) && (
                        <p className="text-[10px] text-cyan-300/70 font-bold m-0">
                            Period: {startDate || '…'} → {endDate || '…'} · activity in range only
                        </p>
                    )}
                </div>
            </div>

            {/* Account ledgers */}
            {accountKeys.length === 0 ? (
                <div className={`p-16 rounded-[2rem] ${glassClass} border border-dashed border-white/15 text-center text-gray-500 font-bold uppercase tracking-widest text-sm`}>
                    No ledger accounts match your filters
                </div>
            ) : accountKeys.map(accKey => {
                const acc = ledgerData[accKey];
                const q = searchTerm.trim().toLowerCase();
                const entries = q
                    ? acc.entries.filter(e =>
                        String(e.description || e.narration || '').toLowerCase().includes(q) ||
                        String(e.partner || '').toLowerCase().includes(q) ||
                        String(e.reference || '').toLowerCase().includes(q) ||
                        String(acc.meta.account_no || '').toLowerCase().includes(q) ||
                        String(acc.meta.name || '').toLowerCase().includes(q))
                    : acc.entries;
                // Auto-expand when searching or single account selected
                const isOpen = expandedAccounts[accKey] === true || selectedAccount !== 'All' || (q && entries.length > 0);
                const balPositive = acc.runningBalance >= 0;

                return (
                    <div key={accKey} className={`rounded-[1.75rem] ${glassClass} border border-white/10 bg-black/50 shadow-xl overflow-hidden`}>
                        {/* Account header */}
                        <button
                            type="button"
                            onClick={() => toggleExpand(accKey)}
                            className="w-full p-5 flex flex-col md:flex-row md:items-center justify-between gap-3 hover:bg-white/[0.03] transition-colors text-left"
                        >
                            <div className="flex items-start gap-4 min-w-0">
                                <div className="shrink-0 w-12 h-12 rounded-2xl bg-cyan-500/15 border border-cyan-400/20 flex items-center justify-center">
                                    <Icons.Layers className="w-5 h-5 text-cyan-400" />
                                </div>
                                <div className="min-w-0">
                                    <div className="flex flex-wrap items-center gap-2">
                                        <span className="font-mono text-cyan-300 font-black text-sm tracking-wide">
                                            {acc.meta.account_no || '—'}
                                        </span>
                                        <span className="text-[9px] px-2 py-0.5 rounded-full bg-white/5 border border-white/10 text-gray-400 uppercase font-black">
                                            {acc.meta.type || 'General'}
                                        </span>
                                        {acc.meta.group && (
                                            <span className="text-[9px] px-2 py-0.5 rounded-full bg-violet-500/10 border border-violet-400/20 text-violet-300 uppercase font-black">
                                                {acc.meta.group}
                                            </span>
                                        )}
                                    </div>
                                    <h3 className="text-base md:text-lg font-black text-white uppercase tracking-tight truncate mt-1">
                                        {acc.meta.name}
                                    </h3>
                                    <p className="text-[10px] text-gray-500 font-bold mt-0.5">
                                        {entries.length} line{entries.length === 1 ? '' : 's'}
                                        {' · '}Dr {fmt(acc.totalDebit)} · Cr {fmt(acc.totalCredit)}
                                    </p>
                                </div>
                            </div>
                            <div className="flex items-center gap-4 shrink-0">
                                <div className="text-right">
                                    <span className="text-[9px] text-gray-500 uppercase font-black block">Running Balance</span>
                                    <span className={`text-lg font-black font-mono ${balPositive ? 'text-emerald-400' : 'text-rose-400'}`}>
                                        {fmt(Math.abs(acc.runningBalance))}
                                        <span className="text-[10px] ml-1 opacity-70">{balPositive ? 'Dr' : 'Cr'}</span>
                                    </span>
                                </div>
                                <Icons.ChevronDown className={`w-5 h-5 text-gray-400 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
                            </div>
                        </button>

                        {isOpen && (
                            <div className="border-t border-white/10">
                                <div className="overflow-x-auto">
                                    <table className="w-full text-left border-collapse min-w-[900px]">
                                        <thead>
                                            <tr className="bg-white/[0.03] text-[10px] uppercase tracking-widest text-cyan-400/90 font-black">
                                                <th className="p-3 w-28">Date</th>
                                                <th className="p-3 w-32">Reference</th>
                                                <th className="p-3 w-28">Code</th>
                                                <th className="p-3 min-w-[220px]">Narration</th>
                                                <th className="p-3 w-36">Partner / Entity</th>
                                                <th className="p-3 text-right w-28">Debit</th>
                                                <th className="p-3 text-right w-28">Credit</th>
                                                <th className="p-3 text-right w-32">Balance</th>
                                            </tr>
                                        </thead>
                                        <tbody className="divide-y divide-white/5">
                                            {entries.length === 0 ? (
                                                <tr>
                                                    <td colSpan={8} className="p-8 text-center text-gray-600 text-xs italic">
                                                        No postings in this period / search
                                                    </td>
                                                </tr>
                                            ) : entries.map((entry, idx) => (
                                                <tr key={idx} className="hover:bg-cyan-500/[0.04] transition-colors text-sm">
                                                    <td className="p-3 font-mono text-[11px] text-gray-300 whitespace-nowrap">{entry.date}</td>
                                                    <td className="p-3 font-mono text-[10px] text-cyan-500/80 truncate max-w-[8rem]" title={entry.reference}>{entry.reference || '—'}</td>
                                                    <td className="p-3 font-mono text-[11px] text-cyan-300 font-bold whitespace-nowrap">{entry.account_code || acc.meta.account_no}</td>
                                                    <td className="p-3 text-[12px] text-gray-200 leading-snug">
                                                        <span className="block">{entry.description || entry.narration || '—'}</span>
                                                        {entry.status && entry.status !== 'Posted' && (
                                                            <span className="inline-block mt-1 text-[9px] px-1.5 py-0.5 rounded bg-amber-500/15 text-amber-400 font-black uppercase">{entry.status}</span>
                                                        )}
                                                    </td>
                                                    <td className="p-3 text-[11px] text-gray-400 truncate max-w-[9rem]" title={entry.partner}>{entry.partner || '—'}</td>
                                                    <td className="p-3 text-right font-mono text-[12px] text-emerald-400">
                                                        {entry.debit > 0 ? fmt(entry.debit) : <span className="text-gray-600">—</span>}
                                                    </td>
                                                    <td className="p-3 text-right font-mono text-[12px] text-rose-400">
                                                        {entry.credit > 0 ? fmt(entry.credit) : <span className="text-gray-600">—</span>}
                                                    </td>
                                                    <td className="p-3 text-right font-mono text-[12px] text-white font-bold">
                                                        {fmt(entry.balanceAfter)}
                                                    </td>
                                                </tr>
                                            ))}
                                        </tbody>
                                        {entries.length > 0 && (
                                            <tfoot>
                                                <tr className="bg-cyan-950/30 border-t border-cyan-500/20 text-[11px] font-black">
                                                    <td colSpan={5} className="p-3 text-right text-gray-400 uppercase tracking-widest">Account totals</td>
                                                    <td className="p-3 text-right font-mono text-emerald-400">{fmt(acc.totalDebit)}</td>
                                                    <td className="p-3 text-right font-mono text-rose-400">{fmt(acc.totalCredit)}</td>
                                                    <td className="p-3 text-right font-mono text-white">{fmt(acc.runningBalance)}</td>
                                                </tr>
                                            </tfoot>
                                        )}
                                    </table>
                                </div>
                            </div>
                        )}
                    </div>
                );
            })}
        </div>
    );
};



