    const { getCollection } = useData();
    
    const slips = getCollection('PAY_SLIP_CRUD') || [];
    const advice = getCollection('PAY_ADVICE_CRUD') || [];
    const taxes = getCollection('PAY_TAX_PENSION_NET_CRUD') || [];
    const employees = getCollection('HR_EMPLOYEE_CRUD') || [];

    const lastSlip = slips[0] || null;
    const lastAdvice = advice[0] || null;
    const lastTax = taxes[0] || null;

    const fullStaffInfo = lastSlip ? employees.find(e => e.name === lastSlip.employee_name) : null;

