const Navigation = ({ menuItems = [], currentView, setCurrentView, expandedFolders = [], setExpandedFolders, checkPermission, glassClass }) => {
    const toggleFolder = (id) => {
        if (!setExpandedFolders) return;
        setExpandedFolders(prev => {
            const list = Array.isArray(prev) ? prev : [];
            return list.includes(id) ? list.filter(x => x !== id) : [...list, id];
        });
    };

    const resolveIcon = (name) => {
        const Icon = (name && Icons[name]) ? Icons[name] : Icons.Circle;
        // Guard against non-component exports from lucide
        if (typeof Icon !== 'function') return Icons.Circle;
        return Icon;
    };

    const renderItem = (item, depth = 0) => {
        if (!item) return null;
        if (checkPermission && item.id && !item.children) {
            try {
                if (!checkPermission(item.id)) return null;
            } catch (_) { /* allow */ }
        }

        const hasChildren = Array.isArray(item.children) && item.children.length > 0;
        const isExpanded = Array.isArray(expandedFolders) && expandedFolders.includes(item.id);
        const isActive = currentView === item.id;
        const IconComp = resolveIcon(item.icon);

        if (hasChildren) {
            return (
                <div key={item.id || item.label} className="mb-1">
                    <button
                        type="button"
                        onClick={() => toggleFolder(item.id)}
                        className={`w-full flex items-center gap-2 px-3 py-2.5 rounded-xl text-left transition-all ${isExpanded ? 'bg-white/5 text-cyan-300' : 'text-gray-400 hover:bg-white/5 hover:text-white'}`}
                        style={{ paddingLeft: `${12 + depth * 10}px` }}
                    >
                        <IconComp className="w-4 h-4 shrink-0 opacity-80" />
                        <span className="text-[11px] font-black uppercase tracking-wider flex-1 truncate">{item.label}</span>
                        {isExpanded
                            ? <Icons.ChevronDown className="w-3.5 h-3.5 shrink-0" />
                            : <Icons.ChevronRight className="w-3.5 h-3.5 shrink-0" />}
                    </button>
                    {isExpanded && (
                        <div className="mt-0.5 space-y-0.5 border-l border-white/5 ml-4">
                            {item.children.map(child => renderItem(child, depth + 1))}
                        </div>
                    )}
                </div>
            );
        }

        return (
            <button
                key={item.id || item.label}
                type="button"
                onClick={() => setCurrentView && setCurrentView(item.id)}
                className={`w-full flex items-center gap-2 px-3 py-2 rounded-xl text-left transition-all ${isActive ? 'bg-cyan-600/30 text-cyan-200 border border-cyan-500/30 shadow-lg shadow-cyan-900/20' : 'text-gray-400 hover:bg-white/5 hover:text-white border border-transparent'}`}
                style={{ paddingLeft: `${12 + depth * 10}px` }}
            >
                <IconComp className={`w-3.5 h-3.5 shrink-0 ${isActive ? 'text-cyan-300' : 'opacity-70'}`} />
                <span className={`text-[11px] font-bold truncate ${isActive ? 'text-white' : ''}`}>{item.label}</span>
            </button>
        );
    };

    return (
        <div className="h-full flex flex-col overflow-hidden">
            <div className="px-4 py-4 border-b border-white/10">
                <p className="text-[10px] font-black text-cyan-400 uppercase tracking-[0.25em]">Modules</p>
                <p className="text-[9px] text-gray-500 mt-0.5">HR · Finance · Payroll · Settings</p>
            </div>
            <nav className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-1">
                {(menuItems || []).map(item => renderItem(item, 0))}
            </nav>
            <div className="p-3 border-t border-white/10 text-[9px] text-gray-600 font-bold uppercase tracking-wider text-center">
                Unity SIS · Sidebar
            </div>
        </div>
    );
};
const HrmAppContent = () => {
    const { isLoggedIn, currentView, setCurrentView, currentUser, checkPermission, logout } = useAuth();
    const { glassOpacityClass, rootStyle, uiSettings } = useUI();
    const { getCollection, allData } = useData();

    // FETCH LIVE ROLES: This is the heartbeat of the April 21 logic
    const allRoles = getCollection('ROLE_CRUD') || [];
    const [showNotifications, setShowNotifications] = useState(false);
    const [notifBadgeCount, setNotifBadgeCount] = useState(0);
    const [mobileNavOpen, setMobileNavOpen] = useState(false);
    const isMobile = useIsMobile(768); 
    const [expandedFolders, setExpandedFolders] = useState(['HR', 'SETTINGS']); 

    const glassClass = `bg-gray-900/70 backdrop-blur-md`;

    
    // If current view is not allowed, fall back to a dashboard the role can open
    useEffect(() => {
        if (!isLoggedIn || !currentUser) return;
        try {
            const roles = typeof getCollection === 'function' ? (getCollection('ROLE_CRUD') || []) : [];
            const ok = checkPermission(currentView, roles);
            if (!ok) {
                const candidates = ['MAT_DASHBOARD_VIEW', 'HR_DASHBOARD_VIEW', 'FIN_DASHBOARD', 'FIN_DASHBOARD_VIEW', 'HR_DASHBOARD', 'MAT_DASHBOARD'];
                const next = candidates.find((id) => checkPermission(id, roles)) || candidates[0];
                if (next && next !== currentView) setCurrentView(next);
            }
        } catch (e) {}
    }, [isLoggedIn, currentUser, currentView, checkPermission, getCollection]);

    if (!isLoggedIn) {
        return <AuthScreen glassClass={glassClass} />;
    }

    // Role / modules[] must allow this app
    if (currentUser && typeof canAccessModule === 'function' && !canAccessModule(currentUser.role, 'finance', currentUser)) {
        return (
            <ModuleAccessGate moduleId="finance" user={currentUser} onLogout={logout} />
        );
    }
    if (currentUser && typeof canAccessModule !== 'function') {
        const _r = String(currentUser.role || '').toLowerCase().replace(/\s+/g, '_');
        const _admin = _r === 'admin' || _r === 'super_admin';
        const _allow = { finance: ['finance_officer','finance_manager','accountant','payroll_officer','hr_manager'], hr: ['hr_manager','hr_staff','hr_officer','recruiter'], material: ['store_manager','inventory_clerk','procurement_officer','warehouse'] }['finance'] || [];
        if (!_admin && !_allow.includes(_r) && !(Array.isArray(currentUser.modules) && currentUser.modules.includes('finance'))) {
            return (
                <ModuleAccessGate moduleId="finance" user={currentUser} onLogout={logout} />
            );
        }
    }



    const exportCSV = (slug) => {
        const data = allData[slug] || [];
        if (!data.length) return;
        const csv = [Object.keys(data[0]).join(','), ...data.map(r => Object.values(r).join(','))].join('\n');
        const blob = new Blob([csv], { type: 'text/csv' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a'); a.href = url; a.download = `${slug}.csv`; a.click();
    };

    return (
        <div className="h-full w-full flex flex-col overflow-hidden relative uu-module-root" style={{ ...(rootStyle || {}), position: "relative", inset: "auto", zIndex: "auto", pointerEvents: "auto" }}>
            <FieldIntelligenceRuntime />
            <MobileStyles />
            <header className={`uu-app-header h-14 shrink-0 flex items-center justify-between px-3 sm:px-6 border-b border-white/10 z-20 ${glassClass}`}>
                <div className="flex items-center gap-2 sm:gap-4 min-w-0">
                    <button
                        type="button"
                        className="md:hidden p-2 rounded-lg bg-white/10 text-cyan-300 shrink-0"
                        aria-label="Open menu"
                        onClick={() => setMobileNavOpen(true)}
                    >
                        <Icons.Menu className="w-5 h-5" />
                    </button>
                    {uiSettings?.logoURL && <img src={uiSettings.logoURL} alt="Logo" className="h-7 sm:h-8 w-auto shrink-0" />}
                    <h1 className="text-sm sm:text-xl font-black text-cyan-400 tracking-tighter italic truncate">UNITY UNIVERSITY</h1>
                </div>

                <div className="flex items-center gap-2 sm:gap-6 shrink-0">
                    <div className="uu-user-block text-right border-r border-white/10 pr-2 sm:pr-6 hidden xs:block sm:block">
                        <p className="text-[10px] sm:text-xs font-bold text-white truncate max-w-[6rem] sm:max-w-none">{currentUser?.username}</p>
                        <p className="text-[8px] sm:text-[9px] text-cyan-500 uppercase font-black truncate">{currentUser?.role}</p>
                    </div>
                    <button type="button" onClick={logout} className="p-2 bg-red-500/10 text-red-500 rounded-lg hover:bg-red-500/20 text-[10px] sm:text-xs font-bold transition-all">LOGOUT</button>
                    <button 
                        type="button"
                        onClick={() => setShowNotifications(!showNotifications)}
                        className={`relative p-2 rounded-full transition-all ${showNotifications ? 'bg-cyan-500 text-white' : 'text-gray-400 hover:text-white'}`}
                        aria-label="Notifications"
                    >
                        <Icons.Bell className="w-5 h-5" />
                        {notifBadgeCount > 0 && (
                            <span className="absolute -top-0.5 -right-0.5 min-w-[18px] h-[18px] px-1 flex items-center justify-center rounded-full bg-rose-600 text-white text-[10px] font-black border-2 border-slate-950 shadow-lg shadow-rose-900/40">
                                {notifBadgeCount > 99 ? '99+' : notifBadgeCount}
                            </span>
                        )}
                    </button>
                </div>
            </header>

            <div className="flex flex-grow overflow-hidden min-h-0 relative">
                {mobileNavOpen && (
                    <div className="uu-sidebar-backdrop md:hidden" onClick={() => setMobileNavOpen(false)} aria-hidden />
                )}
                <aside className={`uu-sidebar-desktop hidden md:block w-[20%] min-w-[260px] max-w-[280px] border-r border-white/10 ${glassClass}`}>
                    <Navigation
                        menuItems={MENU_ITEMS}
                        currentView={currentView}
                        setCurrentView={(id) => checkPermission(id, allRoles) && setCurrentView(id)}
                        expandedFolders={expandedFolders}
                        setExpandedFolders={setExpandedFolders}
                        checkPermission={(id) => checkPermission(id, allRoles)}
                        glassClass={glassClass}
                    />
                </aside>
                <aside className={`uu-sidebar-drawer md:hidden border-r border-white/10 ${glassClass} ${mobileNavOpen ? 'uu-open' : ''}`}>
                    <div className="flex items-center justify-between p-3 border-b border-white/10">
                        <span className="text-xs font-black text-cyan-400 uppercase">Menu</span>
                        <button type="button" className="p-2 text-gray-400" onClick={() => setMobileNavOpen(false)} aria-label="Close menu">
                            <Icons.X className="w-5 h-5" />
                        </button>
                    </div>
                    <Navigation
                        menuItems={MENU_ITEMS}
                        currentView={currentView}
                        setCurrentView={(id) => {
                            if (checkPermission(id, allRoles)) {
                                setCurrentView(id);
                                setMobileNavOpen(false);
                            }
                        }}
                        expandedFolders={expandedFolders}
                        setExpandedFolders={setExpandedFolders}
                        checkPermission={(id) => checkPermission(id, allRoles)}
                        glassClass={glassClass}
                    />
                </aside>

                <main className={`uu-main flex-1 min-w-0 overflow-y-auto overflow-x-hidden ${glassClass} p-3 sm:p-6`}>
                    {/* PASS ROLES DOWN TO RENDERVIEW */}
                    {renderView(currentView, glassClass, getCollection, checkPermission, allRoles, allData)}
                </main>

                <aside className={`${showNotifications ? 'w-[min(100%,320px)] sm:w-[25%] border-l border-white/10 animate-in slide-in-from-right' : 'w-0 overflow-hidden border-0'} ${glassClass} shrink-0 transition-[width] duration-200`}>
                    <div className={showNotifications ? 'h-full' : 'h-0 overflow-hidden opacity-0 pointer-events-none'}>
                        <NotificationBar 
                            glassClass={glassClass} 
                            currentUser={currentUser} 
                            onClose={() => setShowNotifications(false)}
                            onCountChange={(n) => setNotifBadgeCount(Number(n) || 0)}
                        />
                    </div>
                </aside>
            </div>
        </div>
    );
};



