/**
 * Expand day-journal headers + line arrays into ledger legs so TB / GL / P&L / CF
 * see the same balanced postings as Single Transaction CRUD.
 */
export const flattenFinanceLedger = (transactions = [], dayJournals = [], extraLegs = []) => {
    const legs = [];
    const pushLeg = (row) => {
        if (!row) return;
        const st = String(row.status || 'Posted').toLowerCase();
        if (st === 'draft' || st === 'cancelled' || st === 'void') return; // only posted/verified hit TB/GL
        const code = String(row.account_code || row.account_id || row.account_no || '').replace(/^acc-/i, '').trim();
        const debit = Number(row.debit != null ? row.debit : (String(row.type || '').toLowerCase().startsWith('d') ? row.amount : 0)) || 0;
        const credit = Number(row.credit != null ? row.credit : (String(row.type || '').toLowerCase().startsWith('c') ? row.amount : 0)) || 0;
        if (!code && !debit && !credit) return;
        legs.push({
            ...row,
            account_id: code || row.account_id,
            account_code: code || row.account_code,
            account_no: code || row.account_no,
            debit,
            credit,
            amount: debit || credit || Number(row.amount) || 0,
            type: debit > 0 && credit <= 0 ? 'Debit' : credit > 0 ? 'Credit' : (row.type || 'Debit'),
            description: row.description || row.narration || '',
            narration: row.narration || row.description || '',
            status: row.status || 'Posted',
        });
    };

    (Array.isArray(transactions) ? transactions : []).filter(Boolean).forEach((tx) => {
        if (!tx || typeof tx !== 'object') return;
        if (Array.isArray(tx.lines) && tx.lines.length) {
            tx.lines.forEach((ln, i) => {
                pushLeg({
                    ...tx,
                    id: `${tx.id || 'tx'}-L${i}`,
                    account_id: ln.account_id || ln.account_code,
                    account_code: ln.account_id || ln.account_code,
                    account_name: ln.account_name,
                    debit: ln.debit,
                    credit: ln.credit,
                    type: Number(ln.debit) > 0 ? 'Debit' : 'Credit',
                    description: tx.description || tx.narration,
                });
            });
        } else {
            pushLeg(tx);
        }
    });

    const txRefs = new Set(
        (Array.isArray(transactions) ? transactions : [])
            .filter(Boolean)
            .map((x) => String((x && (x.reference || x.id)) || '').trim())
            .filter(Boolean)
    );

    (Array.isArray(dayJournals) ? dayJournals : []).filter(Boolean).forEach((j) => {
        if (!j || typeof j !== 'object') return;
        const jref = String((j.reference != null ? j.reference : j.id) || '').trim();
        // Avoid double-count when the same economic event is already in Single Transaction legs
        if (jref && txRefs.has(jref)) return;
        // Also match soft overlap (e.g. JNL-GRV-001 vs GRV-2026-001) by shared GRV / PAY token
        const soft = (Array.isArray(transactions) ? transactions : []).some((tx) => {
            if (!tx) return false;
            const a = String(tx.reference || tx.id || '');
            const b = jref;
            if (!a || !b) return false;
            if (a === b) return true;
            if (a.includes('GRV') && b.includes('GRV')) {
                const da = a.replace(/\D/g, '');
                const db = b.replace(/\D/g, '');
                if (da && db && da === db) return true;
            }
            return false;
        });
        if (soft) return;

        if (Array.isArray(j.lines) && j.lines.length) {
            j.lines.forEach((ln, i) => {
                pushLeg({
                    id: `${j.id || 'dj'}-L${i}`,
                    date: j.date,
                    partner_name: j.partner_name,
                    partner_type: j.partner_type,
                    account_id: ln.account_id || ln.account_code,
                    account_code: ln.account_id || ln.account_code,
                    account_name: ln.account_name,
                    debit: ln.debit,
                    credit: ln.credit,
                    type: Number(ln.debit) > 0 ? 'Debit' : 'Credit',
                    description: j.description,
                    narration: j.description,
                    reference: j.reference || j.id,
                    cost_center: j.cost_center,
                    location_code: j.location_code,
                    status: j.status || 'Posted',
                    module: j.module || 'FINANCE',
                    source: j.source || 'DAY_JOURNAL',
                });
            });
        }
    });

    (Array.isArray(extraLegs) ? extraLegs : []).forEach(pushLeg);

    // Dedupe by id (mock tx pairs + journal lines may overlap by reference)
    const byId = new Map();
    legs.forEach((L) => {
        const k = String(L.id || `${L.date}-${L.account_code}-${L.debit}-${L.credit}-${L.reference || ''}`);
        if (!byId.has(k)) byId.set(k, L);
    });
    return Array.from(byId.values());
};

export const calculateTrialBalance = (
    data,
    coaData,
    startDate,
    endDate
) => {
    const clean = (id) => {
        if (id === null || id === undefined) return '';
        return String(id).replace(/^acc-/i, '').trim();
    };
    const isValidAccountCode = (code) => /^\d{4}-\d{2}-\d{2}$/.test(String(code || '').trim());
    const resolveAccNo = (acc) => {
        if (!acc || typeof acc !== 'object') return '';
        const candidates = [
            acc.account_no, acc.account_code, acc.accountCode,
            acc['Accounting Key'], acc.accounting_key, acc.id
        ].map(clean).filter(Boolean);
        const valid = candidates.find(isValidAccountCode);
        if (valid) return valid;
        const base = clean(acc.base || acc.base_code || '');
        const cc = clean(acc.cc || acc.cost_center || acc.costCenter || '');
        const loc = clean(acc.loc || acc.location_code || acc.locationCode || '');
        if (/^\d{4}$/.test(base) && cc !== '' && loc !== '') {
            return `${base}-${String(cc).padStart(2, '0')}-${String(loc).padStart(2, '0')}`;
        }
        if (/^\d{4}$/.test(base)) return `${base}-01-10`;
        const four = candidates.find(c => /^\d{4}$/.test(c));
        if (four) return `${four}-01-10`;
        return '';
    };

    // COA only for names/types — never invents balances
    const sanitizedCOA = (coaData && Array.isArray(coaData) && coaData.length > 0) ? coaData : [];
    const coaByNo = {};
    sanitizedCOA.forEach((acc) => {
        const accNo = resolveAccNo(acc);
        if (!accNo || !isValidAccountCode(accNo)) return;
        coaByNo[accNo] = acc;
    });

    const ledger = {};

    const ensureLedgerNode = (accNo, txHint = {}) => {
        if (ledger[accNo]) return ledger[accNo];
        const acc = coaByNo[accNo] || {};
        const typeRaw = acc.type || acc.category || acc.group || 'General';
        const groupRaw = acc.group || acc.category || '';
        ledger[accNo] = {
            account_no: accNo,
            account_code: accNo,
            id: `acc-${accNo}`,
            name: acc.desc || acc.name || acc.description || acc.account_name || acc.short_desc ||
                txHint.account_name || txHint.accountName || accNo,
            description: acc.description || acc.desc || acc.name || acc.account_name ||
                txHint.account_name || accNo,
            type: typeRaw,
            category: groupRaw,
            group: groupRaw,
            cost_center: acc.cost_center || acc.cc || '',
            location_code: acc.location_code || acc.loc || '',
            campus: acc.campus || '',
            unit: acc.unit || '',
            debit: 0,
            credit: 0,
        };
        return ledger[accNo];
    };

    const startTs = startDate ? new Date(startDate).getTime() : new Date('2026-01-01').getTime();
    const endTs = endDate ? new Date(endDate).getTime() : new Date('2099-12-31').getTime();

    // Apply ONLY Single Transaction + Day Journal legs (same treatment; amounts sum)
    if (Array.isArray(data)) {
        data.forEach((tx) => {
            if (!tx || typeof tx !== 'object') return;

            const txId = String(tx.id || '');
            const txDescription = String(tx.description || '').toLowerCase();
            const txNarration = String(tx.narration || '').toLowerCase();
            if (
                txId.startsWith('SYS-') ||
                txDescription.includes('balance forward') ||
                txNarration.includes('balance forward')
            ) {
                return;
            }

            // Date window (optional)
            if (tx.date) {
                const d = new Date(tx.date).getTime();
                if (!Number.isNaN(d) && (d < startTs || d > endTs)) return;
            }

            const txAccId =
                resolveAccNo({
                    account_no: tx.account_no,
                    account_code: tx.account_code || tx.accountCode,
                    id: tx.account_id || tx.accountId,
                    base: tx.base,
                    cc: tx.cc || tx.cost_center,
                    loc: tx.loc || tx.location_code,
                }) ||
                clean(tx.account_id || tx.accountId || tx.account_code || tx.accountCode || tx.account_no);

            if (!txAccId || !isValidAccountCode(txAccId)) return;

            ensureLedgerNode(txAccId, tx);

            let debit = Number(tx.debit || 0);
            let credit = Number(tx.credit || 0);
            if ((!debit && !credit) && Number(tx.amount || 0) > 0) {
                const typ = String(tx.type || '').toLowerCase();
                if (typ.startsWith('d') || typ === 'dr') debit = Number(tx.amount);
                else credit = Number(tx.amount);
            }
            if (!Number.isFinite(debit)) debit = 0;
            if (!Number.isFinite(credit)) credit = 0;
            if (debit === 0 && credit === 0) return;

            ledger[txAccId].debit += debit;
            ledger[txAccId].credit += credit;
        });
    }

    // Activity-only rows. gross_debit/credit = sum of legs; display debit/credit = NET side only
    // so one account never shows both columns unless user chooses "gross" mode in UI.
    const rows = Object.values(ledger)
        .map((node) => {
            const gross_debit = Number(Number(node.debit || 0).toFixed(2));
            const gross_credit = Number(Number(node.credit || 0).toFixed(2));
            const net = Number((gross_debit - gross_credit).toFixed(2));
            // Standard TB: place net on the natural side (Dr if net>0, Cr if net<0)
            const debit = net > 0 ? net : 0;
            const credit = net < 0 ? Math.abs(net) : 0;
            return {
                ...node,
                gross_debit,
                gross_credit,
                debit,
                credit,
                net,
            };
        })
        .filter((node) => node.gross_debit !== 0 || node.gross_credit !== 0)
        .sort((a, b) => String(a.account_no).localeCompare(String(b.account_no)));

    return rows;
};




